{"command":"cat > src/dsq/gojson.py <<'PY'
import math, random, re, base64

class GoJsonError(Exception):
    pass

class RawBytes(bytes):
    """Go []byte value: standard encoding/json marshals as base64 string."""
    pass

def b2s(b):
    if isinstance(b, str):
        return b
    return bytes(b).decode('utf-8', 'surrogateescape')

def s2b(s):
    if isinstance(s, (bytes, bytearray)):
        return bytes(s)
    return s.encode('utf-8', 'surrogateescape')

# ---------- Go float formatting ----------
def _shortest_digits(f):
    """Return (sign, digits, exp10) for abs(f) = digits[0].digits[1:] * 10**exp10.
    digits has no leading/trailing zeros (except value 0 -> ('0',0))."""
    if f == 0:
        return ('0', 0)
    # Python repr gives shortest round-trip decimal.
    r = repr(abs(f)).lower()
    if 'e' in r:
        mant, ex = r.split('e')
        ex = int(ex)
    else:
        mant, ex = r, 0
    if '.' in mant:
        ip, fp = mant.split('.')
    else:
        ip, fp = mant, ''
    # value = (ip+fp as integer) * 10^(ex - len(fp))
    all_digits = ip + fp
    # exponent of the first significant digit:
    # position: integer represented by all_digits has decimal point after len(ip) chars
    # leading zeros strip:
    stripped_lead = 0
    while stripped_lead < len(all_digits) and all_digits[stripped_lead] == '0':
        stripped_lead += 1
    digits = all_digits[stripped_lead:]
    # first significant digit sits at place:
    # The number is 0.all_digits * 10^(ex+len(ip))  ; stripping L leading zeros subtracts L
    exp10 = ex + len(ip) - stripped_lead - 1
    digits = digits.rstrip('0') or '0'
    return (digits, exp10)

def _format_f(digits, exp10):
    # digits[0].rest * 10^exp10 rendered in fixed notation
    if exp10 >= 0:
        if len(digits) > exp10 + 1:
            return digits[:exp10+1] + '.' + digits[exp10+1:]
        else:
            return digits + '0' * (exp10 + 1 - len(digits))
    else:
        return '0.' + '0' * (-exp10 - 1) + digits

def format_float_json(f):
    if math.isnan(f):
        raise GoJsonError('json: unsupported value: NaN')
    if math.isinf(f):
        raise GoJsonError('json: unsupported value: +Inf' if f > 0 else 'json: unsupported value: -Inf')
    if f == 0:
        # Go strconv with -0 gives "-0" in json? encoding/json: strconv.AppendFloat(-0,'f',-1) -> "-0"
        return '-0' if math.copysign(1.0, f) < 0 else '0'
    sign = '-' if f < 0 else ''
    digits, exp10 = _shortest_digits(f)
    a = abs(f)
    if a < 1e-6 or a >= 1e21:
        # 'e' format then cleaned by encoding/json
        if len(digits) > 1:
            mant = digits[0] + '.' + digits[1:]
        else:
            mant = digits
        esign = '+' if exp10 >= 0 else '-'
        return f"{sign}{mant}e{esign}{abs(exp10)}"
    return sign + _format_f(digits, exp10)

def format_float_g(f):
    """Go fmt %v for float64 (strconv.FormatFloat 'g' -1)."""
    if math.isnan(f):
        return 'NaN'
    if math.isinf(f):
        return '+Inf' if f > 0 else '-Inf'
    if f == 0:
        return '-0' if math.copysign(1.0, f) < 0 else '0'
    sign = '-' if f < 0 else ''
    digits, exp10 = _shortest_digits(f)
    # For 'g' with prec=-1, exponent decision uses eprec=6 (observed / Go semantics for shortest)
    if exp10 < -4 or exp10 >= 6:
        if len(digits) > 1:
            mant = digits[0] + '.' + digits[1:]
        else:
            mant = digits
        esign = '+' if exp10 >= 0 else '-'
        return f"{sign}{mant}e{esign}{abs(exp10):02d}"
    return sign + _format_f(digits, exp10)

def format_float_v(f):
    return format_float_g(f)

# ---------- Go string quoting ----------
_NAMED_ESCAPES = {
    0x07: r'\a', 0x08: r'\b', 0x0c: r'\f', 0x0a: r'\n', 0x0d: r'\r', 0x09: r'\t', 0x0b: r'\v',
}

def quote_rune_to_ascii(ch, quote='"'):
    # ch: single-character str (may be surrogateescape byte)
    o = ord(ch)
    if ch == quote:
        return '\\' + quote
    if ch == '\\':
        return r'\\'
    if o in _NAMED_ESCAPES:
        return _NAMED_ESCAPES[o]
    if 0x20 <= o < 0x7f:
        return ch
    if o < 0x80:
        return '\\x%02x' % o
    if 0xDC80 <= o <= 0xDCFF:
        # surrogateescape'd raw byte
        return '\\x%02x' % (o - 0xDC00)
    if o <= 0xFFFF:
        return '\\u%04x' % o
    return '\\U%08x' % o

def quote_to_ascii(s):
    if isinstance(s, (bytes, bytearray)):
        s = b2s(s)
    return '"' + ''.join(quote_rune_to_ascii(c) for c in s) + '"'

def strconv_quote(s):
    """Go strconv.Quote (keeps printable unicode)."""
    if isinstance(s, (bytes, bytearray)):
        s = b2s(s)
    out = ['"']
    for c in s:
        o = ord(c)
        if c == '"':
            out.append('\\"')
        elif c == '\\':
            out.append(r'\\')
        elif o in _NAMED_ESCAPES:
            out.append(_NAMED_ESCAPES[o])
        elif 0xDC80 <= o <= 0xDCFF:
            out.append('\\x%02x' % (o - 0xDC00))
        elif o < 0x20 or o == 0x7f:
            out.append('\\x%02x' % o)
        elif not c.isprintable():
            if o <= 0xFFFF:
                out.append('\\u%04x' % o)
            else:
                out.append('\\U%08x' % o)
        else:
            out.append(c)
    out.append('"')
    return ''.join(out)

def quote_char(c):
    """Go encoding/json quoteChar: returns quoted char literal like 'a', '\\n', '\\x01'."""
    if isinstance(c, int):
        b = c
        if b == 0x27:
            return r"'\''"
        if b == 0x22:
            return r"'\"'"
        if b in _NAMED_ESCAPES:
            return "'" + _NAMED_ESCAPES[b] + "'"
        if 0x20 <= b < 0x7f:
            return "'" + chr(b) + "'"
        return "'\\x%02x'" % b
    # str of length1
    if c == "'":
        return r"'\''"
    if c == '"':
        return r"'\"'"
    o = ord(c)
    if o in _NAMED_ESCAPES:
        return "'" + _NAMED_ESCAPES[o] + "'"
    if 0x20 <= o < 0x7f:
        return "'" + c + "'"
    if o < 0x100:
        return "'\\x%02x'" % o
    return "'" + c + "'"

