from .gojson import quote_char

class JSONError(Exception):
    pass

class EOFErrorJSON(Exception):
    pass

_WS = b' \t\r\n'

class Decoder:
    def __init__(self, data: bytes):
        self.d = bytes(data)
        self.i = 0
        self.n = len(data)

    def eof(self):
        self._skip()
        return self.i >= self.n

    def _skip(self):
        d, n = self.d, self.n
        i = self.i
        while i < n and d[i] in _WS:
            i += 1
        self.i = i

    def decode(self):
        self._skip()
        if self.i >= self.n:
            raise EOFErrorJSON('EOF')
        v = self._value()
        return v

    def _err_char(self, c, context):
        raise JSONError(f"invalid character {quote_char(c)} {context}")

    def _value(self):
        self._skip()
        if self.i >= self.n:
            raise EOFErrorJSON('EOF')
        c = self.d[self.i]
        if c == 0x7b:  # {
            return self._object()
        if c == 0x5b:  # [
            return self._array()
        if c == 0x22:
            return self._string()
        if c == 0x74:  # t
            return self._literal(b'true', True)
        if c == 0x66:
            return self._literal(b'false', False)
        if c == 0x6e:
            return self._literal(b'null', None)
        if c == 0x2d or (0x30 <= c <= 0x39):
            return self._number()
        self._err_char(c, 'looking for beginning of value')

    def _literal(self, word, val):
        start = self.i
        for j, expect in enumerate(word):
            if start + j >= self.n:
                raise EOFErrorJSON('unexpected EOF')
            c = self.d[start+j]
            if c != expect:
                name = word.decode()
                # Go: invalid character 'x' in literal true (expecting 'e')
                raise JSONError(f"invalid character {quote_char(c)} in literal {name} (expecting {quote_char(expect)})")
        self.i = start + len(word)
        return val

    def _object(self):
        # at {
        self.i += 1
        obj = {}
        self._skip()
        if self.i < self.n and self.d[self.i] == 0x7d:
            self.i += 1
            return obj
        while True:
            self._skip()
            if self.i >= self.n:
                raise EOFErrorJSON('unexpected EOF')
            if self.d[self.i] != 0x22:
                self._err_char(self.d[self.i], 'looking for beginning of object key string')
            key = self._string()
            self._skip()
            if self.i >= self.n:
                raise EOFErrorJSON('unexpected EOF')
            if self.d[self.i] != 0x3a:
                self._err_char(self.d[self.i], 'after object key')
            self.i += 1
            val = self._value()
            obj[key] = val
            self._skip()
            if self.i >= self.n:
                raise EOFErrorJSON('unexpected EOF')
            c = self.d[self.i]
            if c == 0x2c:
                self.i += 1
                continue
            if c == 0x7d:
                self.i += 1
                return obj
            self._err_char(c, 'after object key:value pair')

    def _array(self):
        self.i += 1
        arr = []
        self._skip()
        if self.i < self.n and self.d[self.i] == 0x5d:
            self.i += 1
            return arr
        while True:
            v = self._value()
            arr.append(v)
            self._skip()
            if self.i >= self.n:
                raise EOFErrorJSON('unexpected EOF')
            c = self.d[self.i]
            if c == 0x2c:
                self.i += 1
                continue
            if c == 0x5d:
                self.i += 1
                return arr
            self._err_char(c, 'after array element')

    def _string(self):
        # at opening quote
        assert self.d[self.i] == 0x22
        self.i += 1
        out = []
        d, n = self.d, self.n
        while True:
            if self.i >= n:
                raise EOFErrorJSON('unexpected EOF')
            c = d[self.i]
            if c == 0x22:
                self.i += 1
                return ''.join(out)
            if c == 0x5c:  # backslash
                self.i += 1
                if self.i >= n:
                    raise EOFErrorJSON('unexpected EOF')
                e = d[self.i]
                self.i += 1
                if e == 0x22: out.append('"')
                elif e == 0x5c: out.append('\\')
                elif e == 0x2f: out.append('/')
                elif e == 0x62: out.append('\b')
                elif e == 0x66: out.append('\f')
                elif e == 0x6e: out.append('\n')
                elif e == 0x72: out.append('\r')
                elif e == 0x74: out.append('\t')
                elif e == 0x75:  # u
                    cp = self._hex4()
                    if 0xD800 <= cp <= 0xDBFF:
                        # look for low surrogate
                        if self.i + 1 < n and d[self.i] == 0x5c and d[self.i+1] == 0x75:
                            saved = self.i
                            self.i += 2
                            try:
                                lo = self._hex4()
                            except JSONError:
                                # Go: invalid surrogate pair -> replacement, and the second escape is processed? It uses decodeState handling.
                                # Simplify: replacement and keep consumed.
                                lo = None
                            if lo is not None and 0xDC00 <= lo <= 0xDFFF:
                                out.append(chr(0x10000 + ((cp - 0xD800) << 10) + (lo - 0xDC00)))
                            else:
                                out.append('\ufffd')
                                if lo is not None:
                                    # second was a valid \u escape but not low surrogate: Go emits replacement for first and then the second char (unless surrogate)
                                    if 0xD800 <= lo <= 0xDFFF:
                                        out.append('\ufffd')
                                    else:
                                        out.append(chr(lo))
                        else:
                            out.append('\ufffd')
                    elif 0xDC00 <= cp <= 0xDFFF:
                        out.append('\ufffd')
                    else:
                        out.append(chr(cp))
                else:
                    self._err_char(e, 'in string escape code')
                continue
            if c < 0x20:
                self._err_char(c, 'in string literal')
            if c < 0x80:
                out.append(chr(c)); self.i += 1; continue
            # multibyte / invalid
            if c >= 0xF0: ln = 4
            elif c >= 0xE0: ln = 3
            elif c >= 0xC0: ln = 2
            else: ln = 1
            if ln == 1 or self.i + ln > n:
                out.append('\ufffd'); self.i += 1; continue
            chunk = bytes(d[self.i:self.i+ln])
            try:
                s = chunk.decode('utf-8')
                if len(s) != 1 or len(s.encode('utf-8')) != ln:
                    raise ValueError
            except Exception:
                out.append('\ufffd'); self.i += 1; continue
            out.append(s); self.i += ln

    def _hex4(self):
        val = 0
        for _ in range(4):
            if self.i >= self.n:
                raise EOFErrorJSON('unexpected EOF')
            c = self.d[self.i]
            self.i += 1
            if 0x30 <= c <= 0x39:
                val = val*16 + (c-0x30)
            elif 0x61 <= c <= 0x66:
                val = val*16 + (c-0x61+10)
            elif 0x41 <= c <= 0x46:
                val = val*16 + (c-0x41+10)
            else:
                raise JSONError(f"invalid character {quote_char(c)} in \\u hexadecimal character escape")
        return val

    def _number(self):
        d, n = self.d, self.n
        start = self.i
        i = self.i
        # Go scanner-like validation
        if i < n and d[i] == 0x2d:
            i += 1
            if i >= n:
                raise EOFErrorJSON('unexpected EOF')
            if not (0x30 <= d[i] <= 0x39):
                self._err_char(d[i], 'in numeric literal')
        # int part
        if i < n and d[i] == 0x30:
            i += 1
            if i < n and 0x30 <= d[i] <= 0x39:
                # Go: invalid character 'X' after decimal point in numeric literal? Actually for leading zero: stateInNumber -> error "invalid character '1' after ..."?
                # Probe-driven: Go scanner error is: invalid character '1' after top-level value? We'll use a close variant.
                self._err_char(d[i], 'after decimal point in numeric literal')
        else:
            if i >= n or not (0x31 <= d[i] <= 0x39):
                if i < n:
                    self._err_char(d[i], 'in numeric literal')
                raise EOFErrorJSON('unexpected EOF')
            while i < n and 0x30 <= d[i] <= 0x39:
                i += 1
        # fraction
        if i < n and d[i] == 0x2e:
            i += 1
            if i >= n:
                raise EOFErrorJSON('unexpected EOF')
            if not (0x30 <= d[i] <= 0x39):
                self._err_char(d[i], 'after decimal point in numeric literal')
            while i < n and 0x30 <= d[i] <= 0x39:
                i += 1
        # exponent
        if i < n and d[i] in b'eE':
            i += 1
            if i < n and d[i] in b'+-':
                i += 1
            if i >= n:
                raise EOFErrorJSON('unexpected EOF')
            if not (0x30 <= d[i] <= 0x39):
                self._err_char(d[i], 'in exponent of numeric literal')
            while i < n and 0x30 <= d[i] <= 0x39:
                i += 1
        token = bytes(d[start:i])
        self.i = i
        try:
            return float(token.decode('ascii'))
        except OverflowError:
            import math
            return -math.inf if token.startswith(b'-') else math.inf
        except ValueError:
            # extremely large exponent -> float() returns inf in python, shouldn't happen
            import math
            return -math.inf if token.startswith(b'-') else math.inf

def decode_one(data: bytes):
    dec = Decoder(data)
    return dec.decode()

def decode_all_values(data: bytes):
    dec = Decoder(data)
    vals = []
    while True:
        dec._skip()
        if dec.i >= dec.n:
            break
        vals.append(dec.decode())
    return vals
