from .gojson import s2b, _encode_string_bytes_go

class Shape:
    __slots__ = ('kind','array','object','scalar','varied')
    def __init__(self, kind, array=None, object=None, scalar=None, varied=None):
        self.kind = kind
        self.array = array
        self.object = object
        self.scalar = scalar
        self.varied = varied
    def __eq__(self, other):
        if not isinstance(other, Shape):
            return False
        return (self.kind == other.kind and self.array == other.array and self.object == other.object
                and self.scalar == other.scalar and self.varied == other.varied)
    def __repr__(self):
        return f"Shape({self.kind!r},{self.array!r},{self.object!r},{self.scalar!r},{self.varied!r})"

def Unknown(): return Shape('unknown')
def Scalar(name): return Shape('scalar', scalar=name)
def Arr(elem): return Shape('array', array=elem)
def Obj(fields): return Shape('object', object=dict(fields))
def Varied(opts): return Shape('varied', varied=list(opts))
NULL_SCALAR_NAME = 'null'

def shape_from_value(v):
    if v is None:
        return Unknown()
    if isinstance(v, bool):
        return Scalar('boolean')
    if isinstance(v, (int, float)):
        return Scalar('number')
    if isinstance(v, str):
        return Scalar('string')
    if isinstance(v, (bytes, bytearray)):
        return Scalar('string')
    if isinstance(v, (list, tuple)):
        if not v:
            return Arr(Unknown())
        cur = shape_from_value(v[0])
        for el in v[1:]:
            cur = merge_shapes(cur, shape_from_value(el))
        return Arr(cur)
    if isinstance(v, dict):
        return Obj({k: shape_from_value(val) for k, val in v.items()})
    return Unknown()

def _varied_contains(shape, target):
    if shape == target:
        return True
    if shape.kind == 'varied':
        return any(_varied_contains(c, target) for c in shape.varied)
    return False

def merge_shapes(a, b):
    if a == b:
        return a
    if a.kind == 'array' and b.kind == 'array':
        # Bug-compatible: returns element merge unwrapped.
        return merge_shapes(a.array, b.array)
    if a.kind == 'object' and b.kind == 'object':
        out = {}
        for k, av in a.object.items():
            if k in b.object:
                out[k] = merge_shapes(av, b.object[k])
            else:
                out[k] = merge_shapes(av, Scalar(NULL_SCALAR_NAME))
        for k, bv in b.object.items():
            if k not in a.object:
                out[k] = merge_shapes(bv, Scalar(NULL_SCALAR_NAME))
        return Obj(out)
    if a.kind == 'varied' and _varied_contains(a, b):
        return a
    if b.kind == 'varied' and _varied_contains(b, a):
        return b
    return Varied([a, b])

def shape_to_plain(shape):
    # Preserve struct field order for pretty JSON emission below
    d = {}
    d['kind'] = shape.kind
    if shape.kind == 'array':
        d['array'] = shape_to_plain(shape.array)
    elif shape.kind == 'object':
        d['object'] = {k: shape_to_plain(v) for k, v in shape.object.items()}
    elif shape.kind == 'scalar':
        d['scalar'] = shape.scalar
    elif shape.kind == 'varied':
        d['varied'] = [shape_to_plain(v) for v in shape.varied]
    return d

def _indent_encode(v, out, level):
    # Go json.MarshalIndent(plain, "", "  ") but with our dict order preserved.
    ind = b'  ' * level
    ind1 = b'  ' * (level + 1)
    if isinstance(v, dict):
        if not v:
            out += b'{}'; return
        out += b'{\n'
        items = list(v.items())
        # Object maps whose parent is a shape node: shape struct keys are kind/array/... which we keep in order.
        # The 'object' field map entries: apply random order like Go iteration by shuffling only where caller requested? Caller shuffles beforehand.
        for idx, (k, val) in enumerate(items):
            out += ind1
            _encode_string_bytes_go(s2b(k), out)
            out += b': '
            _indent_encode(val, out, level + 1)
            if idx != len(items) - 1:
                out += b','
            out += b'\n'
        out += ind + b'}'
        return
    if isinstance(v, (list, tuple)):
        if not v:
            out += b'[]'; return
        out += b'[\n'
        for idx, el in enumerate(v):
            out += ind1
            _indent_encode(el, out, level + 1)
            if idx != len(v) - 1:
                out += b','
            out += b'\n'
        out += ind + b']'
        return
    if isinstance(v, str):
        _encode_string_bytes_go(s2b(v), out); return
    if v is None:
        out += b'null'; return
    raise TypeError(type(v))

def _shuffle_shape_objects(plain):
    import random
    rng = random.Random()
    try:
        import os
        rng.seed(int.from_bytes(os.urandom(8), 'little'))
    except Exception:
        pass
    def rec(v):
        if isinstance(v, dict):
            if v.get('kind') == 'object' and isinstance(v.get('object'), dict):
                items = list(v['object'].items())
                rng.shuffle(items)
                v['object'] = dict(items)
            for val in v.values():
                rec(val)
        elif isinstance(v, list):
            for el in v:
                rec(el)
    rec(plain)
    return plain

def shape_json_bytes(shape):
    plain = _shuffle_shape_objects(shape_to_plain(shape))
    out = bytearray()
    _indent_encode(plain, out, 0)
    out += b'\n'
    return bytes(out)

def _sorted_keys(d):
    return sorted(d.keys(), key=lambda k: s2b(k))

def shape_pretty_lines(shape, level=0):
    ind = '  ' * level
    if shape.kind == 'scalar':
        return [ind + shape.scalar]
    if shape.kind == 'unknown':
        return [ind + 'Unknown']
    if shape.kind == 'array':
        return [ind + 'Array of'] + shape_pretty_lines(shape.array, level + 1)
    if shape.kind == 'object':
        lines = [ind + 'Object of']
        for k in _sorted_keys(shape.object):
            lines.append('  ' * (level + 1) + k + ' of')
            lines.extend(shape_pretty_lines(shape.object[k], level + 2))
        return lines
    if shape.kind == 'varied':
        lines = [ind + 'Varied of']
        for idx, opt in enumerate(shape.varied):
            sub = shape_pretty_lines(opt, level + 1)
            if idx != len(shape.varied) - 1 and sub:
                sub[-1] = sub[-1] + ' or'
            lines.extend(sub)
        return lines
    return [ind + shape.kind]

def shape_pretty_bytes(shape):
    return ('\n'.join(shape_pretty_lines(shape)) + '\n').encode('utf-8', 'surrogateescape')

def flatten_columns(shape):
    """From an Object shape, produce [(path_tuple, column_name, sqltype)]."""
    cols = []
    def rec(prefix, sh):
        if sh.kind == 'object':
            for k, v in sh.object.items():
                rec(prefix + (k,), v)
            return
        colname = '.'.join(prefix)
        if sh.kind == 'scalar' and sh.scalar == 'number':
            typ = 'REAL'
        elif sh.kind == 'scalar' and sh.scalar == 'boolean':
            typ = 'BOOLEAN'
        else:
            typ = 'TEXT'
        cols.append((prefix, colname, typ))
    if shape.kind == 'object':
        for k, v in shape.object.items():
            rec((k,), v)
    return cols
