    def __repr__(self):
        return f"Shape({self.kind!r},{self.array!r},{self.object!r},{self.scalar!r},{self.varied!r})"

def Unknown(): return Shape('unknown')
def Scalar(name): return Shape('scalar', scalar=name)
def Arr(elem): return Shape('array', array=elem)
def Obj(fields): return Shape('object', object=dict(fields))
def Varied(opts): return Shape('varied', varied=list(opts))
NULL_SCALAR_NAME = 'null'

def shape_from_value(v):
    if v is None:
        return Unknown()
    if isinstance(v, bool):
