def _strip_sql_comments_and_space(sql: bytes) -> bytes:
    out = bytearray()
    i = 0
    n = len(sql)
    while i < n:
        if sql[i:i+2] == b'--':
            # line comment to newline
            j = sql.find(b'\n', i)
            if j == -1:
                break
            i = j + 1
            continue
        if sql[i:i+2] == b'/*':
            j = sql.find(b'*/', i + 2)
            if j == -1:
                break
            i = j + 2
            continue
        c = sql[i]
        if c in b' \t\r\n;':
            i += 1
            continue
        out.append(c)
        i += 1
    return bytes(out)
