                        if saw_stmt and remaining.strip() == b'':
                            break
                        # whitespace/comment/extra-semicolon only at end (or whole query)
                        if saw_stmt and remaining.strip(b' \t\r\n') == b'':
                            break
                        raise HangError()
                    # There is leftover non-comment text but sqlite produced no stmt -> treat as hang if no progress
                    raise HangError()
                if tail_off == offset:
                    raise HangError()
                offset = tail_off
                continue
            saw_stmt = True
            if last_stmt is not None:
                _lib.sqlite3_finalize(last_stmt)
            last_stmt = stmt
            if tail_off >= total:
                offset = tail_off
                break
            offset = tail_off
        if last_stmt is None:
            raise HangError()
        try:
            return self.collect(last_stmt)
        finally:
            _lib.sqlite3_finalize(last_stmt)

def _strip_sql_comments_and_space(sql: bytes) -> bytes:
    out = bytearray()
    i = 0
    n = len(sql)
    while i < n:
        if sql[i:i+2] == b'--':
            # line comment to newline
            j = sql.find(b'\n', i)
            if j == -1:
                break
            i = j + 1
            continue
        if sql[i:i+2] == b'/*':
            j = sql.find(b'*/', i + 2)
            if j == -1:
                break
            i = j + 2
            continue
        c = sql[i]
        if c in b' \t\r\n;':
            i += 1
            continue
        out.append(c)
        i += 1
    return bytes(out)
