def excel_serial_to_datetime(serial, date1904=False):
    if date1904:
        base = datetime.datetime(1904,1,1)
        return base + datetime.timedelta(days=serial)
    # Excel 1900 with leap year bug
    if serial < 1:
        base = datetime.datetime(1899,12,31)
