        from decimal import Decimal, ROUND_HALF_UP
        q=Decimal('1.' + '0'*decs) if decs==0 else Decimal('0.' + '0'*decs)
        # Use repr to avoid binary noise beyond shortest
        dval=Decimal(repr(aval)).quantize(Decimal('1e-%d'%decs) if decs else Decimal('1'), rounding=ROUND_HALF_UP)
        s=f"{dval:.{decs}f}"
        if decs>mandatory and '.' in s:
            # trim optional trailing zeros down to mandatory
            ip,fp=s.split('.')
            fp=fp.rstrip('0')
            if len(fp)<mandatory: fp=fp.ljust(mandatory,'0')
            s=ip+('.'+fp if fp else '')
        else:
            ip=s.split('.')[0]
        if '.' in s:
            ip,fp=s.split('.',1)
