def format_excel_value(raw_value, numfmt_id, custom_fmt, date1904=False):
    if raw_value is None or raw_value=='':
        return ''
    fmt = custom_fmt if custom_fmt else BUILTIN_NUMFMTS.get(numfmt_id, 'General')
    try:
        v=float(raw_value)
    except Exception:
        return str(raw_value)
    if fmt=='General' or numfmt_id==0 and not custom_fmt:
        return _general_number(v)
    if fmt=='@' or numfmt_id==49:
        return str(raw_value)
    sections=_split_format_sections(fmt)
    # Section selection
    sec=sections[0]
    neg=False
    if len(sections)>=2:
        if v<0:
            sec=sections[1]
            v=abs(v); neg=False # section contains its own sign/parens
        elif v==0 and len(sections)>=3:
            sec=sections[2]
    if numfmt_id in DATE_BUILTIN or _is_date_section(sec):
        try:
            dt=excel_serial_to_datetime(v,date1904)
        except Exception:
            return _general_number(v)
        return _format_date(dt,sec)
    return _format_number(v,sec)

# ---------------- XLSX -----------------
def load_xlsx(data: bytes, display_name: str):
    try:
        zf=zipfile.ZipFile(__import__('io').BytesIO(data))
        names=set(zf.namelist())
    except zipfile.BadZipFile:
        raise DsqError('zip: not a valid zip file')
    except Exception as e:
        raise DsqError(str(e))
    def read_xml(name):
        try:
            raw=zf.read(name)
        except KeyError:
            raise DsqError(f'open {name}: file does not exist')
        except zipfile.BadZipFile:
            raise DsqError('zip: not a valid zip file')
        try:
            return ET.fromstring(raw)
        except ET.ParseError as e:
            raise DsqError(str(e))
    # shared strings
    shared=[]
    if 'xl/sharedStrings.xml' in names:
        root=read_xml('xl/sharedStrings.xml')
        for si in root:
            if _local(si.tag)!='si': continue
            parts=[]
            for t in si.iter():
                if _local(t.tag)=='t':
                    # skip phonetic rPh ancestors is hard; ElementTree no parent; phonetic text uses rPh>t too but rare
                    parts.append(t.text or '')
            shared.append(''.join(parts))
    # styles
    custom_fmts={}
    xfs=[]
    if 'xl/styles.xml' in names:
        sroot=read_xml('xl/styles.xml')
        for nf in _findall_deep(sroot,'numFmt'):
            try: custom_fmts[int(nf.get('numFmtId'))]=nf.get('formatCode') or ''
            except Exception: pass
        cellxfs=_find(sroot,'cellXfs')
        if cellxfs is not None:
            for xf in cellxfs:
                try: xfs.append(int(xf.get('numFmtId') or 0))
                except Exception: xfs.append(0)
    # workbook
    wb=read_xml('xl/workbook.xml')
    date1904=False
    for el in wb.iter():
        if _local(el.tag)=='workbookPr' and (el.get('date1904') in ('1','true','True')):
            date1904=True
    rels={}
    if 'xl/_rels/workbook.xml.rels' in names:
        rr=read_xml('xl/_rels/workbook.xml.rels')
        for rel in rr:
            rels[rel.get('Id')]=rel.get('Target')
    sheets_el=_find(wb,'sheets')
    sheet_defs=[]
    if sheets_el is not None:
        for sh in sheets_el:
            if _local(sh.tag)!='sheet': continue
            name=sh.get('name') or ''
            rid=sh.get(f'{{{R_NS}}}id') or sh.get('r:id')
            target=rels.get(rid)
            if target is None:
                continue
            if target.startswith('/'):
                path=target.lstrip('/')
            elif target.startswith('xl/'):
                path=target
            else:
                path='xl/'+target
            # normalize worksheets/../ etc simple
            path=re.sub(r'xl/worksheets/\.\./','xl/',path)
            sheet_defs.append((name,path))
    sheets=[]
    for sheet_name,path in sheet_defs:
        if path not in names:
            # try xl/worksheets/sheetN fallback by index
            continue
        ws=read_xml(path)
        sd=_find(ws,'sheetData')
        matrix=[]
        if sd is not None:
            rows_by_num={}
            max_row=0
            expected_row=1
            for row_el in sd:
                if _local(row_el.tag)!='row': continue
                rnum=row_el.get('r')
                try: ridx=int(rnum) if rnum else expected_row
                except Exception: ridx=expected_row
                expected_row=ridx+1
                cells={}
                max_col=-1
                expected_col=0
                for c in row_el:
                    if _local(c.tag)!='c': continue
                    ref=c.get('r') or ''
                    ci=_col_index(ref)
                    if ci is None or ci<0: ci=expected_col
                    expected_col=ci+1
                    val=_xlsx_cell_value(c,shared,xfs,custom_fmts,date1904)
                    # A bare empty cell with no v/is/f and no style does not extend row (Excelize behaviour)
                    has_content = _find(c,'v') is not None or _find(c,'is') is not None or _find(c,'f') is not None
                    cells[ci]=val
                    if has_content:
                        max_col=max(max_col,ci)
                if max_col<0:
                    row_vals=[]
                else:
                    row_vals=[cells.get(i,'') for i in range(max_col+1)]
                rows_by_num[ridx]=row_vals
                max_row=max(max_row,ridx)
            for ridx in range(1,max_row+1):
                matrix.append(rows_by_num.get(ridx,[]))
        sheets.append((sheet_name,matrix))
    return sheets

def _xlsx_cell_value(c,shared,xfs,custom_fmts,date1904):
    t=c.get('t')
    sidx=c.get('s')
    try: style_idx=int(sidx) if sidx is not None else 0
    except Exception: style_idx=0
    numfmt_id=xfs[style_idx] if 0<=style_idx<len(xfs) else 0
    vel=_find(c,'v')
    vtext=vel.text if vel is not None else None
    fel=_find(c,'f')
    if t=='s':
        if vtext is None: return ''
        try: idx=int(vtext)
        except Exception: return ''
        return shared[idx] if 0<=idx<len(shared) else ''
    if t=='inlineStr':
        isel=_find(c,'is')
        if isel is None: return ''
        return ''.join((t.text or '') for t in isel.iter() if _local(t.tag)=='t')
    if t=='b':
        return 'TRUE' if (vtext=='1' or (vtext or '').lower()=='true') else 'FALSE'
    if t=='e':
        return vtext or ''
    if t=='str':
        return vtext or ''
    if t=='d':
        return vtext or ''
    # numeric / formula
    if vtext is None:
        return ''
    return format_excel_value(vtext,numfmt_id,custom_fmts.get(numfmt_id),date1904)

