TABLE_NS='urn:oasis:names:tc:opendocument:xmlns:table:1.0'
TEXT_NS='urn:oasis:names:tc:opendocument:xmlns:text:1.0'

def _ods_cell_text(cell):
    # text:p paragraphs joined with \n; within: text nodes, text:s spaces; tab/line-break ignored
    paras=[]
    for p in cell:
        if _local(p.tag)!='p': continue
        pieces=[]
        def walk(el):
            if el.text: pieces.append(el.text)
            for ch in el:
                ln=_local(ch.tag)
                if ln=='s':
                    cnt=ch.get(f'{{{TEXT_NS}}}c') or ch.get('text:c') or '1'
                    try: cnt=int(cnt)
                    except Exception: cnt=1
                    pieces.append(' '*cnt)
                elif ln in ('tab','line-break'):
                    pass
                else:
                    walk(ch)
                if ch.tail: pieces.append(ch.tail)
        walk(p)
        paras.append(''.join(pieces))
    return '\n'.join(paras)

def load_ods(data: bytes, display_name: str):
    import io
    try:
        zf=zipfile.ZipFile(io.BytesIO(data))
        names=set(zf.namelist())
        if 'content.xml' not in names:
            raise DsqError(ds_error('zip: not a valid zip file','ods',display_name))
        raw=zf.read('content.xml')
    except DsqError:
        raise
    except zipfile.BadZipFile:
        raise DsqError(ds_error('zip: not a valid zip file','ods',display_name))
    except Exception as e:
        raise DsqError(ds_error(str(e),'ods',display_name))
    try:
        root=ET.fromstring(raw)
    except ET.ParseError as e:
        raise DsqError(ds_error(str(e),'ods',display_name))
    sheets=[]
    # spreadsheet element tables in document order (only direct tables under spreadsheet; nested tables in cells ignored approx)
    # find spreadsheet
    spreadsheet=None
    for el in root.iter():
        if _local(el.tag)=='spreadsheet':
            spreadsheet=el; break
    if spreadsheet is None:
        return sheets
    for table in spreadsheet:
        if _local(table.tag)!='table': continue
        name=table.get(f'{{{TABLE_NS}}}name') or table.get('table:name') or ''
        matrix=[]
        for row_el in table:
            if _local(row_el.tag) not in ('table-row',): 
                # header rows groups etc: descend?
                if _local(row_el.tag) in ('table-header-rows','table-rows','table-row-group'):
                    row_els=[e for e in row_el if _local(e.tag)=='table-row']
                else:
                    continue
            else:
                row_els=[row_el]
            for r_el in row_els:
                rrepeat=r_el.get(f'{{{TABLE_NS}}}number-rows-repeated') or '1'
                try: rrepeat=int(rrepeat)
                except Exception: rrepeat=1
                vals=[]
                for cell in r_el:
                    if _local(cell.tag) not in ('table-cell','covered-table-cell'): continue
                    crepeat=cell.get(f'{{{TABLE_NS}}}number-columns-repeated') or '1'
                    try: crepeat=int(crepeat)
                    except Exception: crepeat=1
                    # cap insane repeats like Excel max columns? Original may expand; cap at maybe 16384
                    if crepeat>16384: crepeat=16384
                    txt=_ods_cell_text(cell)
                    vals.extend([txt]*crepeat)
                # trim trailing empty cells that had no text:p content? Approximate: while vals and last =='' and corresponding cell was plain empty -> we cannot know.
                # Keep as-is, except trim trailing empties if row originally ended with non-repeated empty cell is handled by converter null-fill risk.
                for _ in range(min(rrepeat,1048576)):
                    matrix.append(list(vals))
        sheets.append((name,matrix))
    return sheets

def sheets_to_data(sheets, converter_factory):
    """ sheets: list[(name, matrix)] converter_factory returns a TabularConverter-like with set_headers/add_row.
        Returns rows if one sheet else ordered dict name->rows. """
    conv=converter_factory()
    if len(sheets)<=1:
        if not sheets:
            return []
        name,matrix=sheets[0]
        if not matrix:
            return []
        conv.set_headers(matrix[0])
        return [conv.add_row(r) for r in matrix[1:]]
    out={}
    for name,matrix in sheets:
        if not matrix:
            out[name]=[]; continue
        conv.set_headers(matrix[0])
        out[name]=[conv.add_row(r) for r in matrix[1:]]
    return out
