        matrix=[]
        if sd is not None:
            rows_by_num={}
            max_row=0
            expected_row=1
            for row_el in sd:
                if _local(row_el.tag)!='row': continue
                rnum=row_el.get('r')
                try: ridx=int(rnum) if rnum else expected_row
                except Exception: ridx=expected_row
                expected_row=ridx+1
                cells={}
                max_col=-1
                expected_col=0
                for c in row_el:
                    if _local(c.tag)!='c': continue
                    ref=c.get('r') or ''
                    ci=_col_index(ref)
                    if ci is None or ci<0: ci=expected_col
