        if re.match(r'^[+-]?0o[0-7]+$',s): return int(s,8)
        if re.match(r'^[+-]?0b[01]+$',s): return int(s,2)
        if re.match(r'^[+-]?0[0-7]+$',s) and len(s.lstrip('+-'))>1: return int(s,8)
        if re.match(r'^[+-]?\d+$',s):
            return int(s,10)
