            for p in parts: v=v*60+p
            return sign*v
    except Exception:
        pass
    try:
        if re.match(r'^[+-]?(\d+\.\d*|\.\d+|\d+)([eE][+-]?\d+)$',s) or re.match(r'^[+-]?(\d+\.\d*|\.\d+)$',s):
