def yaml_to_json_value(v):
    if isinstance(v,YamlMap):
        out={}
        for k,val in v.pairs:
            if not isinstance(k,str):
                raise DsqError('json: unsupported type: interface {}')
            out[k]=yaml_to_json_value(val)
        return out
    if isinstance(v,list):
        return [yaml_to_json_value(x) for x in v]
    if isinstance(v,datetime.datetime):
        # Go time.Time JSON marshal RFC3339Nano
        return format_go_time(v)
    if isinstance(v,datetime.date):
        return format_go_time(datetime.datetime(v.year,v.month,v.day,tzinfo=datetime.timezone.utc))
    return v

def format_go_time(dt):
    if dt.tzinfo is None:
        dt=dt.replace(tzinfo=datetime.timezone.utc)
    offset=dt.utcoffset()
    base=dt.strftime('%Y-%m-%dT%H:%M:%S')
    if dt.microsecond:
        frac=('%06d'%dt.microsecond).rstrip('0')
        base+='.'+frac
    if offset==datetime.timedelta(0):
        return base+'Z'
    total=int(offset.total_seconds())
    sign='+' if total>=0 else '-'; total=abs(total)
    return f"{base}{sign}{total//3600:02d}:{(total%3600)//60:02d}"

def parse_yaml_documents(data: bytes):
    text=data.decode('utf-8','surrogateescape')
    p=_Parser(text)
    docs=p.parse_stream()
    return docs
