def _go_unquote_double(token):
    # token includes surrounding quotes
    body=token[1:-1]
    out=[]; i=0
    while i<len(body):
        c=body[i]
        if c!='\\':
            out.append(c); i+=1; continue
        i+=1
        if i>=len(body):
            out.append('\\'); break
        e=body[i]; i+=1
        mp={'n':'\n','t':'\t','r':'\r','a':'\a','b':'\b','f':'\f','v':'\v','\\':'\\','"':'"'}
        if e in mp: out.append(mp[e])
        elif e=='x' and i+1<len(body):
            try: out.append(chr(int(body[i:i+2],16))); i+=2
            except Exception: out.append('x')
        elif e=='u' and i+3<len(body):
            try: out.append(chr(int(body[i:i+4],16))); i+=4
            except Exception: out.append('u')
        elif e=='U' and i+7<len(body):
            try: out.append(chr(int(body[i:i+8],16))); i+=8
            except Exception: out.append('U')
        else:
            out.append(e)
    return ''.join(out)

def parse_logfmt(data: bytes):
    text=data.decode('utf-8','surrogateescape')
    # bufio ScanLines semantics
    lines=text.split('\n')
    # Python: if text ends with \n, split gives trailing '' that scanner wouldn't produce
    if text.endswith('\n'):
        lines=lines[:-1]
    if text=='':
        lines=[]
    rows=[]
    for lineno,line in enumerate(lines,1):
        if line.endswith('\r'):
            line=line[:-1]
        rec={}
        i=0; n=len(line)
        while True:
            while i<n and line[i] in ' \t': i+=1
            if i>=n: break
            if line[i]=='=':
                raise DsqError(f"logfmt syntax error at pos {i+1} on line {lineno}: unexpected '='")
            if line[i]=='"':
                raise DsqError(f'logfmt syntax error at pos {i+1} on line {lineno}: unexpected \'"\'')
            kstart=i
            while i<n and line[i] not in ' \t=':
                if line[i]=='"':
                    raise DsqError(f'logfmt syntax error at pos {i+1} on line {lineno}: unexpected \'"\'')
                i+=1
            key=line[kstart:i]
            if i<n and line[i]=='=':
                i+=1
                if i<n and line[i]=='"':
                    # quoted value
                    startq=i; i+=1; closed=False
                    while i<n:
                        if line[i]=='\\':
                            i+=2; continue
                        if line[i]=='"':
                            closed=True; i+=1; break
                        i+=1
                    if not closed:
                        raise DsqError(f'logfmt syntax error at pos {n+1} on line {lineno}: unterminated quoted value')
                    value=_go_unquote_double(line[startq:i])
                else:
                    vstart=i
                    while i<n and line[i] not in ' \t':
                        if line[i]=='=':
                            raise DsqError(f"logfmt syntax error at pos {i+1} on line {lineno}: unexpected '='")
                        i+=1
                    value=line[vstart:i]
            else:
                value=''
            rec[key]=value
