        if b==0x22: out+=b'\\"'
        elif b==0x5c: out+=b'\\\\'
        elif b==0x0a: out+=b'\\n'
        elif b==0x0d: out+=b'\\r'
        elif b==0x09: out+=b'\\t'
        elif b==0x08: out+=b'\\b'
        elif b==0x0c: out+=b'\\f'
