class CsvParseError(Exception):
    def __init__(self,start_line,line,column,msg):
        self.start_line=start_line; self.line=line; self.column=column; self.msg=msg
    def __str__(self):
        if self.start_line!=self.line:
            return f'record on line {self.start_line}; parse error on line {self.line}, column {self.column}: {self.msg}'
        return f'parse error on line {self.line}, column {self.column}: {self.msg}'

