                elif state=='quoted':
                    if ch=='"':
                        state='afterquote'; closing_quote_pos=(cur_line_no,col); pos+=1; continue
                    field.append(ch); pos+=1; continue
                elif state=='afterquote':
                    if ch=='"':
                        field.append('"'); state='quoted'; pos+=1; continue
                    if ch==delimiter:
                        fields.append(''.join(field)); field=[]; state='start'; pos+=1; continue
