                if had_nl:
                    field.append('\n')
                    idx+=1
                    if idx>=total:
                        # EOF right after newline inside a quote
                        raise CsvParseError(start_line,cur_line_no,raw_len+1,'extraneous or missing " in quoted-field')
                    line_exhausted=False
                    # continue outer with next line without resetting state
                    break
                else:
                    # EOF no newline
                    idx+=1
                    raise CsvParseError(start_line,cur_line_no,raw_len+1,'extraneous or missing " in quoted-field')
