def _go_unquote_double(token):
    # token includes surrounding quotes
    body=token[1:-1]
    out=[]; i=0
    while i<len(body):
        c=body[i]
        if c!='\\':
            out.append(c); i+=1; continue
        i+=1
        if i>=len(body):
            out.append('\\'); break
        e=body[i]; i+=1
        mp={'n':'\n','t':'\t','r':'\r','a':'\a','b':'\b','f':'\f','v':'\v','\\':'\\','"':'"'}
