        elif e=='x' and i+1<len(body):
            try: out.append(chr(int(body[i:i+2],16))); i+=2
            except Exception: out.append('x')
        elif e=='u' and i+3<len(body):
            try: out.append(chr(int(body[i:i+4],16))); i+=4
            except Exception: out.append('u')
        elif e=='U' and i+7<len(body):
            try: out.append(chr(int(body[i:i+8],16))); i+=8
            except Exception: out.append('U')
        else:
            out.append(e)
    return ''.join(out)

