    if state.verbose:
        ts = datetime.datetime.now().strftime('%Y-%m-%dT%H:%M:%S')
        _write_stderr(f"[INFO] {ts} Assumed '{mime}' from '{mime}' given '{display}' when loading file\n".encode('utf-8','surrogateescape'))

def _sql_quote_ident(name):
    return '"' + name.replace('"','""') + '"'

# ---------------- import helpers ----------------
def _import_delimited(db, inp, state):
    rows = inp.csv_rows_original or []
    if not rows:
        return
    cols = list(rows[0].keys())
    _RNG.shuffle(cols)
    typ = 'NUMERIC' if state.convert_numbers else 'TEXT'
    coldefs = ', '.join(f'{_sql_quote_ident(c)} {typ}' for c in cols)
    sql = f'CREATE TABLE "t_{inp.index}"({coldefs})'
    try:
        db.exec_simple(sql)
        if cols:
            placeholders = ','.join(['?']*len(cols))
            ins = f'INSERT INTO "t_{inp.index}" VALUES({placeholders})'
            for r in rows:
                db.insert(ins, [r.get(c) for c in cols])
    except SQLiteError as e:
        raise DsqError(str(e))

def _leaf_value(element, path):
    cur = element
    for comp in path:
        if isinstance(cur, dict) and comp in cur:
            cur = cur[comp]
        else:
            return None
    if isinstance(cur, (dict, list)):
        return go_json_marshal(cur).decode('utf-8', 'surrogateescape')
    return cur

def _input_not_array_msg(name):
    if name:
        return f'Input is not an array of objects: {name}.'
    return 'Input is not an array of objects.'

def _validate_array_objects(inp):
    data = inp.data
    if not isinstance(data, list) or len(data)==0 or any(not isinstance(el, dict) for el in data):
        raise DsqError(_input_not_array_msg(inp.name))

def _import_generic(db, inp, state, temp=True):
    _validate_array_objects(inp)
    shape = inp.shape
    cols = flatten_columns(shape.array)
    cols = list(cols)
    _RNG.shuffle(cols)
    coldefs = ', '.join(f'{_sql_quote_ident(name)} {typ}' for (path,name,typ) in cols)
    temp_kw = 'TEMP ' if temp else ''
    sql = f'CREATE {temp_kw}TABLE "t_{inp.index}" ({coldefs})'
    try:
        db.exec_simple(sql)
        if cols:
            placeholders = ','.join(['?']*len(cols))
            ins = f'INSERT INTO "t_{inp.index}" VALUES({placeholders})'
            for el in inp.data:
                vals=[_leaf_value(el, path) for (path,name,typ) in cols]
                db.insert(ins, vals)
    except SQLiteError as e:
        raise DsqError(str(e))

def _hang_forever():
    while True:
        time.sleep(3600)

# ---------------- placeholder expansion ----------------
_PLACEHOLDER_RE = re.compile(r'\{([0-9]+)\}')

def _expand_and_import(query, inputs, db, state, delimited_preimported=False):
    q = query.replace('{}', '{0}')
    if state.all_delimited:
        if not delimited_preimported:
            if not (state.cache_effective and state.cache_valid):
                for inp in inputs:
                    _import_delimited(db, inp, state)
        def repl_delim(m):
            ds = m.group(1)
            try:
                idx = int(ds)
            except Exception:
                idx = -1
            if ds == str(idx) and 0 <= idx < len(inputs):
                return f'"t_{idx}"'
            return '""'
        return _PLACEHOLDER_RE.sub(repl_delim, q)
    # generic
    imported = set()
    out = []
    last = 0
    for m in _PLACEHOLDER_RE.finditer(q):
        out.append(q[last:m.start()])
        ds = m.group(1)
        if state.cache_effective and state.cache_valid:
            out.append(f'"t_{ds}"')
            last = m.end()
            continue
        # Go strconv.Atoi on 64-bit
        try:
            idx = int(ds)
            if idx > 9223372036854775807:
                raise OverflowError
        except OverflowError:
            raise DsqError(_input_not_array_msg(''))
        if idx >= len(inputs):
            raise PanicExit(panic_index_oob(idx, len(inputs)))
        inp = inputs[idx]
        if ds != str(idx):
            raise DsqError(_input_not_array_msg(inp.name))
        if idx not in imported:
            temp = not state.cache_effective
            _import_generic(db, inp, state, temp=temp)
            imported.add(idx)
        out.append(f'"t_{idx}"')
        last = m.end()
    out.append(q[last:])
    return ''.join(out)

def _set_wal(db):
    try:
        db.query_single('PRAGMA journal_mode=WAL;')
    except SQLiteError as e:
        raise DsqError(str(e))

def execute_query_once(query, inputs, state, repl_db=None, delimited_preimported=False):
    temp_path = None
    close_db = False
    db = repl_db
    if db is None:
        try:
            if state.cache_effective:
                db = DB(state.cache_path)
                close_db = True
                _set_wal(db)
            elif state.all_delimited:
                temp_path = _temp_random_name('dsq-sqlite-shared')
                db = DB(temp_path)
                close_db = True
                _set_wal(db)
            else:
                db = DB(':memory:')
                close_db = True
        except SQLiteError as e:
            raise DsqError(str(e))
    try:
        expanded = _expand_and_import(query, inputs, db, state, delimited_preimported=delimited_preimported)
        try:
            rows = db.run_last(expanded.encode('utf-8','surrogateescape'))
        except HangError:
            _hang_forever()
            return []
        except SQLiteError as e:
            raise DsqError(str(e))
        return rows
    finally:
        if close_db:
            try:
                db.close()
            except Exception:
                pass
            if temp_path:
                for suffix in ('', '-wal', '-shm'):
                    try: os.remove(temp_path+suffix)
                    except OSError: pass

# ---------------- output from JSON bytes ----------------
def output_from_json_bytes(jb, pretty, schema, context='query'):
    if schema:
        try:
            value = decode_one(jb)
        except Exception as e:
            raise DsqError(str(e))
        shp = shape_from_value(value)
        if pretty:
            _write_stdout(shape_pretty_bytes(shp))
        else:
            _write_stdout(shape_json_bytes(shp))
        return
    if pretty:
        try:
            value = decode_one(jb)
        except Exception as e:
            raise DsqError(str(e))
        if not isinstance(value, list):
            raise PanicExit(panic_dump_json(json_len=0x54, addr='0x18', pc='0x23584ce', off='+0x14e', context=context))
        if len(value)==0 or any(not isinstance(el, dict) for el in value):
            raise PanicExit(panic_dump_json(json_len=0x54, addr='0x0', pc='0x23584d2', off='+0x152', context=context))
        _write_stdout(pretty_rows(value))
        return
    _write_stdout(jb + b'\n')

def output_rows(rows, state, context='query'):
    try:
        jb = encode_array_rows(rows)
    except GoJsonError as e:
        raise DsqError(str(e))
    if state.schema or state.pretty:
        output_from_json_bytes(jb, state.pretty, state.schema, context=context)
    else:
        _write_stdout(jb + b'\n')

# ---------------- interactive ----------------
def run_repl(inputs, state):
    db = None
    temp_path = None
    delimited_pre = False
    try:
        if state.cache_effective:
            db = DB(state.cache_path); _set_wal(db)
        elif state.all_delimited:
            temp_path = _temp_random_name('dsq-sqlite-shared')
            db = DB(temp_path); _set_wal(db)
        else:
            db = DB(':memory:')
    except SQLiteError as e:
        raise DsqError(str(e))
    # The REPL outputs pretty tables (or pretty schemas with -c)
    old_pretty = state.pretty
    state.pretty = True
    try:
        if state.all_delimited:
            for inp in inputs:
                _import_delimited(db, inp, state)
            delimited_pre = True
        is_tty = False
        try:
            is_tty = sys.stdin.isatty()
        except Exception:
            is_tty = False
        if is_tty:
            try:
                import readline  # noqa
            except Exception:
                pass
        while True:
            if is_tty:
                try:
                    line = input('dsq> ')
                except EOFError:
                    raise DsqError('EOF')
                except KeyboardInterrupt:
                    # chzyer/readline reports interrupt; continue to a fresh prompt
                    _write_stdout(b'\n')
                    continue
            else:
                raw = sys.stdin.buffer.readline()
                if raw == b'':
                    raise DsqError('EOF')
                if b'\x04' in raw:
                    before = raw.split(b'\x04')[0]
                    if before.strip() == b'' and raw.strip(b'\r\n') == b'\x04':
                        raise DsqError('EOF')
                    if before.strip():
                        _write_stdout(b'\x07')
                    raw = before
                line = raw.decode('utf-8','surrogateescape')
                if line.endswith('\n'):
                    line = line[:-1]
                    if line.endswith('\r'):
                        line = line[:-1]
            trimmed = line.strip()
            if trimmed == '':
                continue
            if trimmed == 'exit':
                _write_stdout(b'bye\n')
                return
            rows = execute_query_once(line, inputs, state, repl_db=db, delimited_preimported=delimited_pre)
            output_rows(rows, state, context='repl')
    finally:
        state.pretty = old_pretty
        if db is not None:
            try: db.close()
            except Exception: pass
        if temp_path:
            for suffix in ('','-wal','-shm'):
                try: os.remove(temp_path+suffix)
                except OSError: pass

# ---------------- cache-file mode ----------------
def handle_cache_file(inputs, state, query, dump_mode):
    if state.cache_path is None:
        # Hash creation failed but load succeeded (rare): Go would default to normal mode; -D has no path to print.
        # Fall back to printing nothing.
        return
    if dump_mode or state.schema:
        _write_stdout((state.cache_path + '\n').encode('utf-8','surrogateescape'))
        return
    if state.all_delimited:
        db = None
        try:
            db = DB(state.cache_path); _set_wal(db)
            if not state.cache_valid:
                for inp in inputs:
                    _import_delimited(db, inp, state)
        except SQLiteError as e:
            raise DsqError(str(e))
        finally:
            if db is not None:
                db.close()
        _write_stdout((state.cache_path + '\n').encode('utf-8','surrogateescape'))
        return
    _write_stdout((state.cache_path + '\n').encode('utf-8','surrogateescape'))

# ---------------- main ----------------
def _main(argv):
    state = State()
    positional = []
    stdin_type = None
    sql_file = None
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ('-h','--help'):
            _write_stderr(HELP_TEXT); return 0
        if a in ('-v','--version'):
            _write_stderr(VERSION_TEXT); return 0
        if a in ('-p','--pretty'):
            state.pretty=True
        elif a in ('-c','--schema'):
            state.schema=True
        elif a in ('-n','--convert-numbers'):
            state.convert_numbers=True
        elif a in ('-C','--cache'):
            state.cache=True
        elif a in ('-D','--cache-file'):
            state.cache_file=True
        elif a in ('-i','--interactive'):
            state.interactive=True
        elif a == '--verbose':
            state.verbose=True
        elif a in ('-s','--stdin'):
            if i+1 >= len(argv):
                _print_error('Must specify stdin mimetype.')
                return 1
            i += 1; stdin_type = argv[i]
        elif a in ('-f','--file'):
            if i+1 >= len(argv):
                _print_error('Must specify a SQL file.')
                return 1
            i += 1; sql_file = argv[i]
        else:
            positional.append(a)
        i += 1

    stdin_present = stdin_type not in (None, '')
    stdin_raw = None
    stdin_name = None
    try:
        if stdin_present:
            stdin_name = _temp_random_name('dsq-stdin')
            state.stdin_temp = stdin_name
            stdin_raw = sys.stdin.buffer.read()
            with open(stdin_name, 'wb') as f:
                f.write(stdin_raw)
        query = None
        explicit = False
        if sql_file is not None:
            content = _read_sql_file(sql_file)
            if len(content)==0:
                _print_error('SQL file is empty.')
                return 1
            query = content.decode('utf-8','surrogateescape')
            explicit = True
        total_for_query = len(positional) + (1 if stdin_present else 0)
        files_positional = list(positional)
        if sql_file is None and total_for_query > 1:
            candidate = positional[-1]
            query = candidate; explicit = True
            if ' ' in candidate:
                files_positional = positional[:-1]
        # specs: list of (display name, is_stdin)
        specs = []
        if stdin_present:
            specs.append((stdin_name, True))
        for fn in files_positional:
            specs.append((fn, False))
        if len(specs)==0:
            _print_error('No input files.')
            return 1
        # mimetypes (for mode determination + later)
        spec_mimes = []
        for disp, is_stdin in specs:
            if is_stdin:
                spec_mimes.append(mime_for_stdin_arg(stdin_type))
            else:
                spec_mimes.append(mime_for_name(disp))
        state.all_delimited = all(m in DELIMITED_MIMES for m in spec_mimes)
        # Cache hashing (before loading)
        want_cache_hash = state.cache or state.cache_file or state.interactive
        if want_cache_hash:
            h = hashlib.sha1()
            hash_err = None
            for (disp, is_stdin) in specs:
                try:
                    data = stdin_raw if is_stdin else _read_input_raw(disp)
                except DsqError as e:
                    hash_err = str(e); break
                h.update(data)
            if hash_err is not None:
                _write_stderr(f"Error creating hash for cache mode: {hash_err}, defaulting to normal mode\n".encode('utf-8','surrogateescape'))
                state.cache_disabled=True
                state.cache_path=None
            else:
                state.cache_path = os.path.join(tempfile.gettempdir(), f"dsq-cache-{h.hexdigest()}.db")
                try:
                    state.cache_valid = os.path.exists(state.cache_path) and os.path.getsize(state.cache_path)>0
                except OSError:
                    state.cache_valid=False
                if not state.cache_valid:
                    _write_stderr(b"Cache invalid, re-import required.\n")
        # Load inputs sequentially
        inputs = []
        for idx, ((disp, is_stdin), mime) in enumerate(zip(specs, spec_mimes)):
            if mime is None:
                _print_error(f'Unknown mimetype for file: {disp}.')
                return 1
            raw = stdin_raw if is_stdin else _read_input_raw(disp)
            _verbose(state, mime, disp)
            inp = load_input(idx, disp, mime, raw, convert_numbers=state.convert_numbers, all_delimited=state.all_delimited)
            inp.is_stdin = is_stdin
            inputs.append(inp)
        dump_mode = not explicit
        if state.cache_file:
            handle_cache_file(inputs, state, query, dump_mode)
            return 0
        if state.interactive:
            run_repl(inputs, state)
            return 0
        if dump_mode:
            inp = inputs[0]
            try:
                jb = inp.get_json_bytes()
            except GoJsonError as e:
                raise DsqError(str(e))
            if state.schema or state.pretty:
                output_from_json_bytes(jb, state.pretty, state.schema, context='dump')
            else:
                _write_stdout(jb + b'\n')
            return 0
        rows = execute_query_once(query, inputs, state)
        output_rows(rows, state, context='query')
        return 0
    finally:
        if state.stdin_temp:
            try: os.remove(state.stdin_temp)
            except OSError: pass

def main(argv=None):
    try:
        signal.signal(signal.SIGINT, signal.SIG_DFL)
    except Exception:
        pass
    try:
        signal.signal(signal.SIGPIPE, signal.SIG_DFL)
    except Exception:
        pass
    if argv is None:
        argv = sys.argv[1:]
    try:
        return _main(argv)
    except PanicExit as p:
        _print_error(p.text)
        return 2
    except DsqError as e:
        _print_error(str(e))
        return 1
    except BrokenPipeError:
        return 1
