import struct
class ThriftError(Exception): pass

CT_STOP=0
CT_TRUE=1
CT_FALSE=2
CT_BYTE=3
CT_I16=4
CT_I32=5
CT_I64=6
CT_DOUBLE=7
CT_BINARY=8
CT_LIST=9
CT_SET=10
CT_MAP=11
CT_STRUCT=12

class Reader:
    def __init__(self,data,pos=0):
        self.d=data; self.i=pos
    def read_byte(self):
        if self.i>=len(self.d): raise ThriftError('unexpected EOF')
        b=self.d[self.i]; self.i+=1; return b
    def read_varint(self):
        result=0; shift=0
        while True:
            b=self.read_byte()
            result |= (b & 0x7f) << shift
            if not (b & 0x80): break
            shift+=7
            if shift>70: raise ThriftError('varint too long')
        return result
    def read_zigzag(self):
        n=self.read_varint()
        return (n>>1) ^ -(n & 1)
    def read_value(self,ctype):
        if ctype==CT_TRUE: return True
        if ctype==CT_FALSE: return False
        if ctype==CT_BYTE:
            b=self.read_byte(); return b-256 if b>127 else b
        if ctype in (CT_I16,CT_I32,CT_I64): return self.read_zigzag()
        if ctype==CT_DOUBLE:
            if self.i+8>len(self.d): raise ThriftError('unexpected EOF')
            v=struct.unpack('<d',self.d[self.i:self.i+8])[0]; self.i+=8; return v
        if ctype==CT_BINARY:
            ln=self.read_varint()
            if self.i+ln>len(self.d): raise ThriftError('unexpected EOF')
            v=bytes(self.d[self.i:self.i+ln]); self.i+=ln; return v
        if ctype in (CT_LIST,CT_SET):
            hdr=self.read_byte(); size=hdr>>4; etype=hdr & 0x0f
            if size==15: size=self.read_varint()
            return [self.read_value(etype) for _ in range(size)]
        if ctype==CT_MAP:
            size=self.read_varint()
            if size==0: return {}
            hdr=self.read_byte(); ktype=hdr>>4; vtype=hdr & 0x0f
            out={}
            for _ in range(size):
                k=self.read_value(ktype); v=self.read_value(vtype)
                try: out[k]=v
                except Exception: out[str(k)]=v
            return out
        if ctype==CT_STRUCT:
            return self.read_struct()
        raise ThriftError(f'unknown compact type {ctype}')
    def read_struct(self):
        out={}
        last_id=0
        while True:
            hdr=self.read_byte()
            ctype=hdr & 0x1f
            if ctype==CT_STOP:
                break
            delta=(hdr & 0xe0)>>5
            if delta==0:
                fid=self.read_zigzag()
            else:
                fid=last_id+delta
            last_id=fid
            # boolean field types encode value in type
            if ctype in (CT_TRUE,CT_FALSE):
                out[fid]=(ctype==CT_TRUE)
            else:
                out[fid]=self.read_value(ctype)
        return out

def parse_struct(data,pos=0):
    r=Reader(data,pos)
    v=r.read_struct()
    return v,r.i
