class SnappyError(Exception): pass

def decompress(data):
    # raw snappy block
    i=0
    # varint uncompressed length
    result_len=0; shift=0
    while i<len(data):
        b=data[i]; i+=1
        result_len|=(b&0x7f)<<shift
        if not (b&0x80): break
        shift+=7
    out=bytearray()
    n=len(data)
    while i<n:
        tag=data[i]; i+=1
        typ=tag&3
        if typ==0:
            ln=tag>>2
            if ln<60:
                length=ln+1
            else:
                extra=ln-59
                if i+extra>n: raise SnappyError('literal length EOF')
                length=int.from_bytes(data[i:i+extra],'little')+1; i+=extra
            if i+length>n: raise SnappyError('literal EOF')
            out += data[i:i+length]; i+=length
        elif typ==1:
            length=((tag>>2)&7)+4
            if i>=n: raise SnappyError('offset EOF')
            offset=((tag>>5)<<8)|data[i]; i+=1
            _copy(out,offset,length)
        elif typ==2:
            length=(tag>>2)+1
            if i+2>n: raise SnappyError('offset EOF')
            offset=int.from_bytes(data[i:i+2],'little'); i+=2
            _copy(out,offset,length)
        else:
            length=(tag>>2)+1
            if i+4>n: raise SnappyError('offset EOF')
            offset=int.from_bytes(data[i:i+4],'little'); i+=4
            _copy(out,offset,length)
    if len(out)!=result_len:
        # Some callers may pass data where declared len mismatches due framing; return out if non-empty
        # Raise to allow caller fallback
        raise SnappyError(f'snappy length mismatch {len(out)} != {result_len}')
    return bytes(out)

def _copy(out,offset,length):
    if offset==0 or offset>len(out): raise SnappyError('invalid offset')
    for _ in range(length):
        out.append(out[-offset])

def decompress_avro_block(data):
    # Avro OCF snappy blocks append 4-byte big-endian CRC32 of uncompressed data
    try:
        return decompress(data)
    except Exception:
        if len(data)>4:
            return decompress(data[:-4])
        raise
