        if clen==0 or i+clen>len(data): break
        out+=_lz4_block_decompress(data[i:i+clen],dlen); i+=clen; ok=True
        if len(out)>=uncompressed_size: break
    if ok and len(out)>=uncompressed_size:
        return out[:uncompressed_size]
    # fallback raw
    return _lz4_block_decompress(data,uncompressed_size)

# schema tree helpers
class ColInfo:
    pass

def _build_schema_tree(elements):
    # elements preorder. Build nested nodes with children.
    pos=0
    def parse_one():
        nonlocal pos
        el=elements[pos]; pos+=1
        node={
            'type': el.get(1), 'type_length': el.get(2), 'repetition': el.get(3,0),
            'name': (el.get(4) or b'').decode('utf-8','surrogateescape') if isinstance(el.get(4),bytes) else str(el.get(4) or ''),
            'converted': el.get(6), 'scale': el.get(7), 'precision': el.get(8), 'logical': el.get(10),
            'children':[]
        }
        nc=el.get(5) or 0
        for _ in range(nc):
            node['children'].append(parse_one())
        return node
    if not elements: return None
    return parse_one()

def _logical_info(node):
    log=node.get('logical')
    info={}
    if isinstance(log,dict):
        # union: one field id present
        for k,v in log.items():
            info['kind_id']=k; info['value']=v
            # decimal: {1:scale,2:precision}; time/timestamp {1:utc,2:{unit field:{}}}
            if isinstance(v,dict):
                if 1 in v and 2 in v and k==5:
                    info['scale']=v.get(1); info['precision']=v.get(2)
                if k in (7,8):
                    unit=v.get(2)
                    if isinstance(unit,dict) and unit:
                        info['unit']=next(iter(unit.keys()))  # 1 millis 2 micros 3 nanos
                if k==10:
                    info['bitwidth']=v.get(1); info['signed']=v.get(2)
    return info

def _convert_value(raw, node):
    if raw is None: return None
    pt=node.get('type')
    conv=node.get('converted')
    log=_logical_info(node)
    lk=log.get('kind_id')
    # Logical STRING=1, ENUM=4, JSON=12 ; converted UTF8=0 ENUM=4
    if isinstance(raw,(bytes,bytearray)) and pt in (BYTE_ARRAY,FIXED):
        is_string = (conv in (0,4,19)) or (lk in (1,4,12))
        # DECIMAL on byte arrays
        scale=None; prec=None
        if conv==5 or lk==5:
            scale=node.get('scale') if node.get('scale') is not None else log.get('scale',0)
            unscaled=int.from_bytes(raw,'big',signed=True)
            return _format_decimal(unscaled, scale or 0)
        if is_string:
            return bytes(raw).decode('utf-8','surrogateescape')
        if lk==14 and len(raw)==16:
            import uuid
            return str(uuid.UUID(bytes=bytes(raw)))
        # binary -> base64 string as JSON would
        import base64
        return base64.b64encode(bytes(raw)).decode()
    if pt==INT96 and isinstance(raw,(bytes,bytearray)) and len(raw)==12:
        nanos=struct.unpack('<Q',raw[:8])[0]; julian=struct.unpack('<I',raw[8:12])[0]
        # Julian day to date: unix epoch julian day 2440588
        days=julian-2440588
        dt=datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)+datetime.timedelta(days=int(days),seconds=nanos//1_000_000_000, microseconds=(nanos%1_000_000_000)//1000)
        # Go parquet-go may return int96 as string timestamp? Use nanoseconds since epoch as int to be safe? Return RFC3339 if there is time component flag unknown.
        # xitongsys parquet-go converts INT96 to string via parquet.Int96ToTime -> JSON time. Use Go time format.
        from .yamlmini import format_go_time
        return format_go_time(dt)
    if isinstance(raw,int):
        # decimal on ints
        if conv==5 or lk==5:
            scale=node.get('scale') if node.get('scale') is not None else log.get('scale',0)
            return _format_decimal(raw, scale or 0)
        # unsigned logical ints / converted UINT
        if lk==10 and log.get('signed') is False:
            bw=log.get('bitwidth') or (32 if pt==INT32 else 64)
            return raw & ((1<<bw)-1)
        if conv in (14,15,16,17):  # UINT_8/16/32/64 old numbering approx
            bw={14:8,15:16,16:32,17:64}.get(conv,32)
            return raw & ((1<<bw)-1)
        return raw
    return raw

def _format_decimal(unscaled, scale):
    if scale==0:
        return str(unscaled)
    sign='-' if unscaled<0 else ''
    digits=str(abs(unscaled)).rjust(scale+1,'0')
    return f"{sign}{digits[:-scale]}.{digits[-scale:]}"

def mangle_name(name):
    # parquet-go (PARGO) struct field name sanitisation observed
    out=[]
    for ch in name:
        if ('A'<=ch<='Z') or ('a'<=ch<='z') or ('0'<=ch<='9') or ch=='_':
            out.append(ch)
        else:
            out.append(str(ord(ch)))
    mangled=''.join(out)
    if not mangled or not (('A'<=mangled[0]<='Z') or ('a'<=mangled[0]<='z') or mangled[0]=='_'):
        mangled='PARGO_PREFIX_'+mangled
    # Also names starting with digits after transform get prefix above; lowercase start is kept (to verify with generated files later)
    return mangled

def read_parquet(raw, name):
    if len(raw)<8:
        raise DsqError(f'seek {name}: invalid argument')
    if raw[:4]!=b'PAR1' or raw[-4:]!=b'PAR1':
        # Original library seeking based on footer length may produce this for tiny files
        # Try to determine by length
        raise DsqError(f'seek {name}: invalid argument')
    footer_len=struct.unpack('<I',raw[-8:-4])[0]
    footer_start=len(raw)-8-footer_len
    if footer_start<4:
        raise DsqError(f'seek {name}: invalid argument')
    try:
        meta,_=parse_struct(raw[footer_start:footer_start+footer_len])
    except Exception as e:
        raise DsqError(str(e))
    schema_elements=meta.get(2) or []
    root=_build_schema_tree(schema_elements)
    if root is None:
        return []
    leaves=[]
    # Support only flat root children primitives, and one level of optional groups containing one primitive? For now flat.
    def collect(node,path,max_def,max_rep):
        rep=node.get('repetition') or 0
        # repetition: 0 required,1 optional,2 repeated
        nd=max_def+(1 if rep in (1,2) else 0)
        nr=max_rep+(1 if rep==2 else 0)
        if not node.get('children'):
            leaves.append({'node':node,'path':path+[node['name']],'max_def':nd,'max_rep':nr})
        else:
            for ch in node['children']:
                collect(ch,path+[node['name']] if node is not root else [], nd, nr)
    # root itself is group
    for ch in root.get('children') or []:
        collect(ch,[],0,0)
    # Check flatness: paths length 1 and max_rep 0; nested unsupported fallback still decode flat leaves but building rows will use leaf name
    row_groups=meta.get(4) or []
    all_rows=[]
    for rg in row_groups:
        num_rows=rg.get(3) or 0
        columns_meta=rg.get(1) or []
        col_values=[]
        for col_idx,chunk in enumerate(columns_meta):
            leaf=leaves[col_idx] if col_idx<len(leaves) else leaves[-1]
            vals=_read_column(raw,chunk,leaf)
            col_values.append(vals)
        for r in range(num_rows):
            row={}
            for ci,leaf in enumerate(leaves[:len(col_values)]):
                v=col_values[ci][r] if r < len(col_values[ci]) else None
                row[mangle_name(leaf['node']['name'])]=_convert_value(v,leaf['node'])
            all_rows.append(row)
    return all_rows

def _read_column(data, chunk, leaf):
    meta=chunk.get(3) or {}
    ptype=meta.get(1)
    if ptype is None: ptype=leaf['node'].get('type')
    codec=meta.get(4) or 0
    num_values=meta.get(5) or 0
    total_compressed=meta.get(7) or 0
    dict_offset=meta.get(11)
    data_offset=meta.get(9)
    start=dict_offset if dict_offset is not None else data_offset
    if start is None:
        start=chunk.get(2) or 0
    offset=start
    end=start+total_compressed if total_compressed else len(data)
    dictionary=[]
    values=[]
    max_def=leaf['max_def']; max_rep=leaf['max_rep']
    type_length=leaf['node'].get('type_length')
    while len(values)<num_values and offset<end:
        r=Reader(data,offset)
        try:
            header=r.read_struct()
        except Exception as e:
            raise DsqError(str(e))
        header_len=r.i-offset
        page_type=header.get(1)
        uncomp_size=header.get(2) or 0
        comp_size=header.get(3) or 0
        page_data_start=offset+header_len
        comp_data=data[page_data_start:page_data_start+comp_size]
        next_offset=page_data_start+comp_size
        if page_type==2:  # dictionary page
            dh=header.get(7) or {}
            dnum=dh.get(1) or 0
            # denc=dh.get(2)
            try:
                raw=_decompress(comp_data,codec,uncomp_size)
            except DsqError: raise
            except Exception as e: raise DsqError(str(e))
            dictionary,_=_decode_plain(raw,ptype,dnum,type_length)
            offset=next_offset; continue
        if page_type==0:
            dh=header.get(5) or {}
            nvals=dh.get(1) or 0
            enc=dh.get(2); def_enc=dh.get(3); rep_enc=dh.get(4)
            raw=_decompress(comp_data,codec,uncomp_size)
            rest=raw
            rep_levels=[0]*nvals; def_levels=[max_def]*nvals
            if max_rep>0:
                bw=max(1,(max_rep).bit_length())
                if rep_enc==ENC_RLE:
                    rep_levels,rest=_decode_rle_bitpacked(rest,bw,nvals,length_prefixed=True)
                elif rep_enc==ENC_BIT_PACKED:
                    rep_levels=_decode_bitpacked_deprecated(rest,bw,nvals); rest=rest[(bw*nvals+7)//8:]
            if max_def>0:
                bw=max(1,(max_def).bit_length())
                if def_enc==ENC_RLE:
                    def_levels,rest=_decode_rle_bitpacked(rest,bw,nvals,length_prefixed=True)
                elif def_enc==ENC_BIT_PACKED:
                    def_levels=_decode_bitpacked_deprecated(rest,bw,nvals); rest=rest[(bw*nvals+7)//8:]
                else:
                    def_levels,rest=_decode_rle_bitpacked(rest,bw,nvals,length_prefixed=True)
            nonnull=sum(1 for d in def_levels if d>=max_def)
            decoded=_decode_values(rest,enc,ptype,nonnull,type_length,dictionary)
            it=iter(decoded)
            for d in def_levels:
                values.append(next(it) if d>=max_def else None)
            offset=next_offset; continue
        if page_type==3:
            dh=header.get(8) or {}
            nvals=dh.get(1) or 0; nnull=dh.get(2) or 0
            enc=dh.get(4); def_len=dh.get(5) or 0; rep_len=dh.get(6) or 0
            is_compressed=dh.get(7)
            if is_compressed is None: is_compressed=True
            rep_data=comp_data[:rep_len]
            def_data=comp_data[rep_len:rep_len+def_len]
            values_data=comp_data[rep_len+def_len:]
            if is_compressed and codec!=0:
                # uncompressed size includes levels
                vsize=uncomp_size-rep_len-def_len
                values_raw=_decompress(values_data,codec,vsize)
            else:
                values_raw=values_data
            def_levels=[max_def]*nvals
            if max_def>0:
                bw=max(1,(max_def).bit_length())
                def_levels,_=_decode_rle_bitpacked(def_data,bw,nvals,length_prefixed=False)
            nonnull=nvals-nnull
            decoded=_decode_values(values_raw,enc,ptype,nonnull,type_length,dictionary)
            it=iter(decoded)
            for d in def_levels:
                values.append(next(it) if d>=max_def else None)
            offset=next_offset; continue
        # index page or unknown: skip
        offset=next_offset
    return values[:num_values]
