import struct, gzip, math, datetime
from .util import DsqError
from .thrift_compact import Reader, parse_struct, ThriftError
from .snappy import decompress as snappy_decompress
from .gojson import RawBytes

# Physical types
BOOLEAN=0; INT32=1; INT64=2; INT96=3; FLOAT=4; DOUBLE=5; BYTE_ARRAY=6; FIXED=7
ENC_PLAIN=0; ENC_PLAIN_DICT=2; ENC_RLE=3; ENC_BIT_PACKED=4; ENC_DELTA_BINARY=5; ENC_DELTA_LENGTH=6; ENC_DELTA_BYTE=7; ENC_RLE_DICT=8; ENC_BYTE_STREAM_SPLIT=9

class _BitReaderLSB:
    def __init__(self,data):
        self.d=data; self.pos=0
    def read(self,width):
        if width==0: return 0
        v=0
        for k in range(width):
            byte_idx=self.pos//8; bit=self.pos%8
            if byte_idx>=len(self.d): break
            if (self.d[byte_idx]>>bit)&1: v |= (1<<k)
            self.pos+=1
        return v
class _BitReaderMSB:
    def __init__(self,data):
        self.d=data; self.pos=0
    def read(self,width):
        v=0
        for _ in range(width):
            byte_idx=self.pos//8; bit=7-(self.pos%8)
            if byte_idx < len(self.d) and ((self.d[byte_idx]>>bit)&1): v=(v<<1)|1
            else: v=(v<<1)
            self.pos+=1
        return v

def _decode_rle_bitpacked(data, bit_width, count, length_prefixed=False):
    if length_prefixed:
        if len(data)<4: return [],data
        ln=struct.unpack('<I',data[:4])[0]
        body=data[4:4+ln]; rest=data[4+ln:]
    else:
        body=data; rest=b''
    vals=[]
    i=0
    if bit_width==0:
        return [0]*count, rest
    nbytes=(bit_width+7)//8
    while len(vals)<count and i<len(body):
        # varint header
        header=0; shift=0
        while i<len(body):
            b=body[i]; i+=1
            header|=(b&0x7f)<<shift
            if not (b&0x80): break
            shift+=7
        if header & 1:
            groups=header>>1
            total=groups*8
            nbytes_packed=groups*bit_width
            chunk=body[i:i+nbytes_packed]; i+=nbytes_packed
            br=_BitReaderLSB(chunk)
            for _ in range(total):
                if len(vals)>=count: break
                vals.append(br.read(bit_width))
        else:
            run=header>>1
            raw=body[i:i+nbytes]; i+=nbytes
            v=int.from_bytes(raw.ljust(nbytes,b'\x00'),'little') if raw else 0
            # mask to bit width
            if bit_width<64: v &= ((1<<bit_width)-1)
            vals.extend([v]*min(run,count-len(vals)))
    return vals, rest

def _decode_bitpacked_deprecated(data, bit_width, count):
    br=_BitReaderMSB(data)
    return [br.read(bit_width) for _ in range(count)]

def _uleb(data,i):
    v=0; shift=0
    while i<len(data):
        b=data[i]; i+=1
        v|=(b&0x7f)<<shift
        if not (b&0x80): break
        shift+=7
    return v,i
def _zig(data,i):
    v,i=_uleb(data,i)
    return (v>>1) ^ -(v&1), i

def _decode_delta_binary(data, count):
    i=0
    block_size,i=_uleb(data,i)
    miniblocks,i=_uleb(data,i)
    total,i=_uleb(data,i)
    first,i=_zig(data,i)
    vals=[first]
    if count==0:
        return vals[:0]
    if miniblocks==0:
        return vals[:count]
    vals_per_miniblock=block_size//miniblocks if miniblocks else 0
    while len(vals)<count:
        if i>=len(data): break
        min_delta,i=_zig(data,i)
        if i+miniblocks>len(data): break
        widths=list(data[i:i+miniblocks]); i+=miniblocks
        for w in widths:
            nbytes=(w*vals_per_miniblock+7)//8
            chunk=data[i:i+nbytes]; i+=nbytes
            br=_BitReaderLSB(chunk)
            for _ in range(vals_per_miniblock):
                if len(vals)>=count: break
                delta=br.read(w) if w else 0
                vals.append(vals[-1]+min_delta+delta)
            if len(vals)>=count: break
    return vals[:count]

def _decode_plain(data, ptype, count, type_length=None):
    vals=[]; i=0
    if ptype==BOOLEAN:
        # bit packed LSB
        for k in range(count):
            byte=data[k//8] if k//8<len(data) else 0
            vals.append(bool((byte>>(k%8))&1))
        return vals, data[(count+7)//8:]
    if ptype==INT32:
        for _ in range(count):
            vals.append(struct.unpack_from('<i',data,i)[0]); i+=4
    elif ptype==INT64:
        for _ in range(count):
            vals.append(struct.unpack_from('<q',data,i)[0]); i+=8
    elif ptype==INT96:
        for _ in range(count):
            vals.append(data[i:i+12]); i+=12
    elif ptype==FLOAT:
        for _ in range(count):
            vals.append(struct.unpack_from('<f',data,i)[0]); i+=4
    elif ptype==DOUBLE:
        for _ in range(count):
            vals.append(struct.unpack_from('<d',data,i)[0]); i+=8
    elif ptype==BYTE_ARRAY:
        for _ in range(count):
            ln=struct.unpack_from('<I',data,i)[0]; i+=4
            vals.append(bytes(data[i:i+ln])); i+=ln
    elif ptype==FIXED:
        ln=type_length or 0
        for _ in range(count):
            vals.append(bytes(data[i:i+ln])); i+=ln
    else:
        raise DsqError('parquet: unknown physical type')
    return vals, data[i:]

def _decode_values(data, encoding, ptype, count, type_length, dictionary):
    if count==0:
        return []
    if encoding==ENC_PLAIN:
        v,_=_decode_plain(data,ptype,count,type_length); return v
    if encoding in (ENC_PLAIN_DICT,ENC_RLE_DICT):
        if not data: return []
        bw=data[0]
        idx,_=_decode_rle_bitpacked(data[1:],bw,count,length_prefixed=False)
        return [dictionary[j] if 0<=j<len(dictionary) else None for j in idx]
    if encoding==ENC_RLE:
        # Used for boolean (bit width 1). Values are length-prefixed hybrid.
        if ptype==BOOLEAN:
            idx,_=_decode_rle_bitpacked(data,1,count,length_prefixed=True)
            return [bool(x) for x in idx]
        # fallback: dictionary indices?
        bw=data[0] if data else 0
        idx,_=_decode_rle_bitpacked(data[1:],bw,count,length_prefixed=False)
        return idx
    if encoding==ENC_BIT_PACKED:
        # deprecated; bit width based on dictionary size or max for ints? For dictionary encoding old style first byte?
        if dictionary:
            bw=max(1,(len(dictionary)-1).bit_length())
            idx=_decode_bitpacked_deprecated(data,bw,count)
            return [dictionary[j] if 0<=j<len(dictionary) else None for j in idx]
        bw={INT32:32,INT64:64,BOOLEAN:1}.get(ptype,32)
        return _decode_bitpacked_deprecated(data,bw,count)
    if encoding==ENC_DELTA_BINARY:
        return _decode_delta_binary(data,count)
    if encoding==ENC_DELTA_LENGTH:
