        # Re-walk delta encoding to find offset of bytes: we need consumed length. Approx: lengths encoding is at start; find by re-decoding with a tracking variant.
        offset=_delta_binary_consumed(data,count)
        vals=[]; i=offset
        for ln in lengths:
            vals.append(bytes(data[i:i+ln])); i+=ln
