    if encoding==ENC_DELTA_BYTE:
        prefixes=_decode_delta_binary(data,count)
        off1=_delta_binary_consumed(data,count)
        suffix_lens=_decode_delta_binary(data[off1:],count)
        off2=off1+_delta_binary_consumed(data[off1:],count)
        vals=[]; i=off2; prev=b''
        for pre,suf in zip(prefixes,suffix_lens):
            suffix=bytes(data[i:i+suf]); i+=suf
