        for k in range(count):
            b=bytes(data[k + s*count] if k+s*count < len(data) else 0 for s in range(width))
            raw.append(b)
        if ptype==FLOAT: return [struct.unpack('<f',b)[0] for b in raw]
        if ptype==DOUBLE: return [struct.unpack('<d',b)[0] for b in raw]
        if ptype==INT32: return [struct.unpack('<i',b)[0] for b in raw]
        if ptype==INT64: return [struct.unpack('<q',b)[0] for b in raw]
