def _delta_binary_consumed(data,count):
    i=0
    block_size,i=_uleb(data,i); miniblocks,i=_uleb(data,i); total,i=_uleb(data,i); first,i=_zig(data,i)
    vals=1
    if miniblocks==0: return i
    per=block_size//miniblocks if miniblocks else 0
    while vals<count:
        _,i=_zig(data,i)
        widths=list(data[i:i+miniblocks]); i+=miniblocks
        for w in widths:
            i += (w*per+7)//8
            vals += per
            if vals>=count: break
    return i

def _decompress(data, codec, uncompressed_size):
    if codec==0:
        return data
    if codec==1:
        return snappy_decompress(data)
    if codec==2:
        return gzip.decompress(data)
    if codec==4:
        # try brotli lib via ctypes if present
        try:
            import ctypes
            lib=ctypes.CDLL('libbrotlidec.so.1')
            out=ctypes.create_string_buffer(uncompressed_size)
            outlen=ctypes.c_size_t(uncompressed_size)
            rc=lib.BrotliDecoderDecompress(len(data), data, ctypes.byref(outlen), out)
            if rc==1: return out.raw[:outlen.value]
        except Exception:
            pass
        raise DsqError('parquet: unsupported codec BROTLI')
    if codec==6:
        try:
            import ctypes
            lib=ctypes.CDLL('libzstd.so.1')
            out=ctypes.create_string_buffer(uncompressed_size)
            n=lib.ZSTD_decompress(out, uncompressed_size, data, len(data))
            if n>0: return out.raw[:n]
        except Exception:
            pass
        raise DsqError('parquet: unsupported codec ZSTD')
    if codec in (5,7):
        return _lz4_decompress(data, uncompressed_size, codec)
    raise DsqError(f'parquet: unsupported codec {codec}')

def _lz4_block_decompress(data, out_len):
    out=bytearray(); i=0
    n=len(data)
