from .snappy import decompress as snappy_decompress

# Type kinds
TK_BOOLEAN=0; TK_BYTE=1; TK_SHORT=2; TK_INT=3; TK_LONG=4; TK_FLOAT=5; TK_DOUBLE=6; TK_STRING=7; TK_BINARY=8; TK_TIMESTAMP=9; TK_LIST=10; TK_MAP=11; TK_STRUCT=12; TK_UNION=13; TK_DECIMAL=14; TK_DATE=15; TK_VARCHAR=16; TK_CHAR=17; TK_TIMESTAMP_INSTANT=18
# Stream kinds
SK_PRESENT=0; SK_DATA=1; SK_LENGTH=2; SK_DICT_DATA=3; SK_DICT_COUNT=4; SK_SECONDARY=5; SK_ROW_INDEX=6; SK_BLOOM=7; SK_BLOOM_UTF8=8
# Encodings
ENC_DIRECT=0; ENC_DICTIONARY=1; ENC_DIRECT_V2=2; ENC_DICTIONARY_V2=3
# Compression
COMP_NONE=0; COMP_ZLIB=1; COMP_SNAPPY=2; COMP_LZO=3; COMP_LZ4=4; COMP_ZSTD=5

def _decompress_orc_stream(raw, comp):
    out=b''; i=0
    if comp==COMP_NONE:
        return raw
    while i < len(raw):
        if i+3>len(raw): break
        header=int.from_bytes(raw[i:i+3],'little'); i+=3
        is_orig=header&1; clen=header>>1
        chunk=raw[i:i+clen]; i+=clen
        if is_orig:
            out+=chunk
        else:
            if comp==COMP_ZLIB:
                out+=zlib.decompress(chunk,-15)
            elif comp==COMP_SNAPPY:
                out+=snappy_decompress(chunk)
            elif comp==COMP_ZSTD:
                import ctypes
                lib=ctypes.CDLL('libzstd.so.1')
                # frame content size may be in frame; allocate a large buffer based on ZSTD_getFrameContentSize
                size=lib.ZSTD_getFrameContentSize(chunk,len(chunk))
                if size<=0: size=262144*4
                buf=ctypes.create_string_buffer(size)
                n=lib.ZSTD_decompress(buf,size,chunk,len(chunk))
                out+=buf.raw[:n]
            elif comp==COMP_LZ4:
                from .parquet_reader import _lz4_block_decompress
                # ORC LZ4 blocks are raw LZ4 blocks; expected size unknown (block size) - decode by giving a big cap via decoder ignoring cap when 0
                out+=_lz4_block_decompress(chunk,0)
            else:
                raise DsqError(f'orc: unsupported compression {comp}')
    return out

class _BitsMSB:
    def __init__(self,data):
        self.d=data; self.pos=0
    def read(self,width):
        v=0
        for _ in range(width):
            idx=self.pos//8; bit=7-(self.pos%8)
            if idx<len(self.d) and ((self.d[idx]>>bit)&1): v=(v<<1)|1
            else: v <<=1
            self.pos+=1
        return v
    def align_byte(self):
        if self.pos%8: self.pos += 8-(self.pos%8)

def _varint(data,i):
    v=0; shift=0
    while i<len(data):
        b=data[i]; i+=1
        v|=(b&0x7f)<<shift
        if not (b&0x80): break
        shift+=7
    return v,i
def _zz(v):
    return (v>>1) ^ -(v&1)
def _signed_varint(data,i):
    v,i=_varint(data,i); return _zz(v),i

class _IntReaderV2:
    def __init__(self,data,signed):
        self.d=data; self.i=0; self.signed=signed
        self.buf=[]; self.buf_i=0
    def read(self,count):
        out=[]
        while len(out)<count:
            if self.buf_i>=len(self.buf):
                self._next_run()
                if not self.buf and self.i>=len(self.d): break
            take=min(count-len(out),len(self.buf)-self.buf_i)
            out.extend(self.buf[self.buf_i:self.buf_i+take]); self.buf_i+=take
        return out
    def _finish(self,vals):
        if self.signed:
            vals=[_zz(v & ((1<<64)-1)) if isinstance(v,int) else v for v in vals]
        self.buf=vals; self.buf_i=0
    def _next_run(self):
        if self.i>=len(self.d): self.buf=[]; return
        b0=self.d[self.i]; self.i+=1
        kind=b0>>6
        if kind==0:
            width=((b0>>3)&7)+1
            count=(b0&7)+3
            raw=self.d[self.i:self.i+width]; self.i+=width
            v=int.from_bytes(raw.ljust(width,b'\x00'),'big')
            self._finish([v]*count)
            return
        if self.i>=len(self.d): self.buf=[]; return
        b1=self.d[self.i]; self.i+=1
        width=((b0>>1)&0x1f)+1
        length=(((b0&1)<<8)|b1)+1
        if kind==1:
            nbytes=(width*length+7)//8
            chunk=self.d[self.i:self.i+nbytes]; self.i+=nbytes
            br=_BitsMSB(chunk)
            vals=[br.read(width) for _ in range(length)]
            self._finish(vals); return
        if kind==3:
            first,self.i=_signed_varint(self.d,self.i)
            delta_base,self.i=_signed_varint(self.d,self.i)
            vals=[first]
            if length>1:
                if width==0:
                    vals.extend([vals[-1]+delta_base for _ in range(length-1)])
                else:
                    nbytes=(width*(length-1)+7)//8
                    chunk=self.d[self.i:self.i+nbytes]; self.i+=nbytes
                    br=_BitsMSB(chunk)
                    for _ in range(length-1):
                        vals.append(vals[-1]+delta_base+br.read(width))
            self.buf=vals; self.buf_i=0; return
        if kind==2:
            if self.i>=len(self.d): self.buf=[]; return
            third=self.d[self.i]; self.i+=1
            base_width=(third>>4)+1
            patch_width=(third&15)+1
            base_raw=self.d[self.i:self.i+base_width]; self.i+=base_width
            # base is signed big-endian (two's complement) of the pre-zigzag value? ORC stores base as signed value.
            base=int.from_bytes(base_raw.ljust(base_width,b'\x00'),'big',signed=True)
            if self.i>=len(self.d): self.buf=[]; return
            fourth=self.d[self.i]; self.i+=1
            patch_gap_width=(fourth>>5)+1
            patch_count=fourth&31
            nbytes=(width*length+7)//8
            chunk=self.d[self.i:self.i+nbytes]; self.i+=nbytes
            br=_BitsMSB(chunk)
            vals=[br.read(width) if width else 0 for _ in range(length)]
            if patch_count:
                pw=patch_width+patch_gap_width
                pbytes=(pw*patch_count+7)//8
                pchunk=self.d[self.i:self.i+pbytes]; self.i+=pbytes
                pbr=_BitsMSB(pchunk)
                pos=0
                for _ in range(patch_count):
                    packed=pbr.read(pw)
                    gap=packed & ((1<<patch_gap_width)-1) if patch_gap_width else 0
                    patch_val=packed>>patch_gap_width
                    pos += gap
                    if pos<length:
                        vals[pos] = vals[pos] | (patch_val<<width)
                    pos += 1
            result=[base+v for v in vals]
            # In patched-base, base & offsets already yield signed values (no extra zigzag on offsets), but
            # if the writer zigzag encoded before subtracting base for signed streams, base would be zigzag of min.
            # Apache ORC converts signed values to unsigned via zigzag BEFORE RLE, and base is stored zigzagged as unsigned big-endian.
            # Our signed interpretation would then be wrong for negative mins. Detect heurstically: if signed, interpret base_raw as unsigned zigzag
            if self.signed:
                base_u=int.from_bytes(base_raw.ljust(base_width,b'\x00'),'big')
                result=[_zz(base_u+v) for v in vals]
            self.buf=result; self.buf_i=0; return

class _IntReaderV1:
    def __init__(self,data,signed):
        self.d=data; self.i=0; self.signed=signed; self.buf=[]; self.buf_i=0
    def read(self,count):
        out=[]
        while len(out)<count:
            if self.buf_i>=len(self.buf):
                self._next_run()
                if not self.buf and self.i>=len(self.d): break
            take=min(count-len(out),len(self.buf)-self.buf_i)
            out.extend(self.buf[self.buf_i:self.buf_i+take]); self.buf_i+=take
        return out
    def _finish(self,vals):
        if self.signed: vals=[_zz(v) for v in vals]
        self.buf=vals; self.buf_i=0
    def _next_run(self):
        if self.i>=len(self.d): self.buf=[]; return
        b0=self.d[self.i]; self.i+=1
        kind=b0>>6
        if kind==0:
            width=((b0>>3)&7)+1; count=(b0&7)+3
            raw=self.d[self.i:self.i+width]; self.i+=width
            v=int.from_bytes(raw.ljust(width,b'\x00'),'big')
            self._finish([v]*count); return
        if self.i>=len(self.d): self.buf=[]; return
        b1=self.d[self.i]; self.i+=1
        width=((b0>>1)&0x1f)+1  # in v1 this is byte width
        length=(((b0&1)<<8)|b1)+1
        if kind==1:
            vals=[]
            for _ in range(length):
                raw=self.d[self.i:self.i+width]; self.i+=width
                vals.append(int.from_bytes(raw.ljust(width,b'\x00'),'big'))
            self._finish(vals); return
        if kind==3:
            first,self.i=_signed_varint(self.d,self.i)
            delta_base,self.i=_signed_varint(self.d,self.i)
            vals=[first]
            # In V1 delta, following values are byte-width direct deltas? Width is byte width of each delta offset.
            for _ in range(length-1):
                raw=self.d[self.i:self.i+width]; self.i+=width
                off=int.from_bytes(raw.ljust(width,b'\x00'),'big')
                vals.append(vals[-1]+delta_base+off)
            self.buf=vals; self.buf_i=0; return
        if kind==2:
            # Patched base v1: similar header, base byte width in third byte high nibble, patch values are byte-width?
            third=self.d[self.i]; self.i+=1
            base_width=(third>>4)+1; patch_width=(third&15)+1
            base_raw=self.d[self.i:self.i+base_width]; self.i+=base_width
            base_u=int.from_bytes(base_raw.ljust(base_width,b'\x00'),'big')
            fourth=self.d[self.i]; self.i+=1
            patch_gap_width=(fourth>>5)+1; patch_count=fourth&31
            vals=[]
            for _ in range(length):
                raw=self.d[self.i:self.i+width]; self.i+=width
                vals.append(int.from_bytes(raw.ljust(width,b'\x00'),'big'))
            # patches are bitpacked with patch_width bits? Reuse v2-ish logic on bits
            if patch_count:
                pw=patch_width+patch_gap_width
                pbytes=(pw*patch_count+7)//8
                pchunk=self.d[self.i:self.i+pbytes]; self.i+=pbytes
                pbr=_BitsMSB(pchunk); pos=0
                for _ in range(patch_count):
                    packed=pbr.read(pw); gap=packed & ((1<<patch_gap_width)-1); pv=packed>>patch_gap_width
                    pos+=gap
                    if pos<length: vals[pos]=vals[pos]|(pv<<(width*8))
                    pos+=1
            result=[base_u+v for v in vals]
            self._finish(result); return

def _make_int_reader(data, encoding_kind, signed):
    if encoding_kind in (ENC_DIRECT_V2,ENC_DICTIONARY_V2):
        return _IntReaderV2(data,signed)
    return _IntReaderV1(data,signed)

class _ByteRLE:
    def __init__(self,data):
        self.d=data; self.i=0; self.buf=b''; self.buf_i=0
    def read_bytes(self,count):
        out=bytearray()
        while len(out)<count:
            if self.buf_i>=len(self.buf):
                if self.i>=len(self.d): break
                ctrl=self.d[self.i]; self.i+=1
                sc=ctrl-256 if ctrl>127 else ctrl
                if sc<0:
                    ln=-sc
                    self.buf=self.d[self.i:self.i+ln]; self.i+=ln
                else:
                    ln=sc+3
                    val=self.d[self.i:self.i+1]; self.i+=1
                    self.buf=val*ln
                self.buf_i=0
            take=min(count-len(out),len(self.buf)-self.buf_i)
            out+=self.buf[self.buf_i:self.buf_i+take]; self.buf_i+=take
        return bytes(out)
    def read_bools(self,count):
        packed=self.read_bytes((count+7)//8)
        out=[]
        for k in range(count):
            byte=packed[k//8] if k//8<len(packed) else 0
            out.append(bool((byte>>(7-(k%8)))&1))
        return out

class _Column:
    def __init__(self, type_id):
        self.type_id=type_id
        self.streams={}  # (kind,seq) -> bytes
        self.encoding_kind=ENC_DIRECT
        self.dict_size=0
    def stream(self,kind,seq=0):
        return self.streams.get((kind,seq),b'')

class _Stripe:
    def __init__(self,cols,encodings,types,num_rows,writer_tz):
        self.cols=cols; self.types=types; self.num_rows=num_rows; self.writer_tz=writer_tz
        self._readers={}
    def present(self,col_id,count):
        col=self.cols.get(col_id)
        if col is None or (SK_PRESENT,0) not in col.streams:
            return [True]*count
        key=('present',col_id)
        if key not in self._readers:
            self._readers[key]=_ByteRLE(col.stream(SK_PRESENT))
        return self._readers[key].read_bools(count)
    def int_reader(self,col_id,kind,signed,seq=0):
        key=('int',col_id,kind,seq,signed)
        if key not in self._readers:
            col=self.cols[col_id]
            self._readers[key]=_make_int_reader(col.stream(kind,seq),col.encoding_kind,signed)
        return self._readers[key]

def _type_list(footer):
    types=[]
    for t in get_msgs(footer,4):
        types.append({
            'kind': get_uint(t,1),
            'subtypes': get_packed_uints(t,2),
            'fieldNames': [v.decode('utf-8','surrogateescape') for (w,v) in t.get(3,[])],
            'maximumLength': get_uint(t,4),
            'precision': get_uint(t,5),
            'scale': get_uint(t,6),
        })
    return types

def read_orc(data,name):
    if len(data)<1:
        # mimic Go orc library panic for tiny files will be handled as error for now
        raise DsqError('orc: invalid file')
    ps_len=data[-1]
    if len(data)<1+ps_len:
        raise DsqError('orc: invalid file')
    ps_raw=data[-1-ps_len:-1]
    try:
        ps=parse_message(ps_raw)
    except Exception as e:
        raise DsqError(str(e))
    footer_len=get_uint(ps,1) or 0
    comp=get_uint(ps,2) or 0
    meta_len=get_uint(ps,5) or 0
    ps_start=len(data)-1-ps_len
    footer_start=ps_start-footer_len
    if footer_start<0:
        raise DsqError('orc: invalid file')
    foot_dec=_decompress_orc_stream(data[footer_start:ps_start],comp)
    footer=parse_message(foot_dec)
    types=_type_list(footer)
    if not types:
        return []
    root=types[0]
    all_rows=[]
    for stripe_info in get_msgs(footer,3):
        off=get_uint(stripe_info,1) or 0; il=get_uint(stripe_info,2) or 0; dl=get_uint(stripe_info,3) or 0; fl=get_uint(stripe_info,4) or 0; nrows=get_uint(stripe_info,5) or 0
        sf_dec=_decompress_orc_stream(data[off+il+dl:off+il+dl+fl],comp)
        sf=parse_message(sf_dec)
        writer_tz=(get_bytes(sf,3) or b'').decode('utf-8','replace')
        encs=get_msgs(sf,2)
        cols={}
        for idx,e in enumerate(encs):
            c=_Column(idx)
            c.encoding_kind=get_uint(e,1) or 0
            c.dict_size=get_uint(e,2) or 0
            cols[idx]=c
        streams=get_msgs(sf,1)
        pos=off
        for st in streams:
            skind=get_uint(st,1); scol=get_uint(st,2) or 0; slen=get_uint(st,3) or 0; sseq=get_uint(st,4) or 0
            raw_stream=data[pos:pos+slen]; pos+=slen
            if skind==SK_ROW_INDEX:
                continue
            if scol not in cols:
                cols[scol]=_Column(scol)
            dec=_decompress_orc_stream(raw_stream,comp) if slen else b''
            cols[scol].streams[(skind,sseq)]=dec
        stripe=_Stripe(cols,encs,types,nrows,writer_tz)
        vals=_read_node(stripe,0,nrows,root_level=True)
        # vals for root struct is list of dicts
        if isinstance(vals,list):
            for v in vals:
                if isinstance(v,dict): all_rows.append(v)
                elif v is None:
                    # null root row: all fields null
                    all_rows.append({fn:None for fn in root.get('fieldNames',[])})
                else:
                    all_rows.append({'_col0':v})
    return all_rows

def _read_node(stripe,col_id,count,root_level=False):
    typ=stripe.types[col_id] if col_id < len(stripe.types) else {'kind':TK_STRING}
    kind=typ['kind']
    present=stripe.present(col_id,count)
    nonnull=sum(1 for p in present if p)
    def interleave(vals):
        it=iter(vals); return [next(it) if p else None for p in present]
    if kind==TK_STRUCT:
        child_vals=[]
        for sub in typ.get('subtypes',[]):
            child_vals.append(_read_node(stripe,sub,nonnull))
        names=typ.get('fieldNames',[])
        out=[]
        for i in range(nonnull):
            row={}
            for j,sub in enumerate(typ.get('subtypes',[])):
                fname=names[j] if j<len(names) else f'_col{j}'
                row[fname]=child_vals[j][i]
            out.append(row)
        return interleave(out)
    if kind==TK_LIST:
        if not typ.get('subtypes'): return interleave([[] for _ in range(nonnull)])
        elem_type=typ['subtypes'][0]
        lengths=stripe.int_reader(col_id,SK_LENGTH,False).read(nonnull) if nonnull else []
        total=sum(lengths)
        elems=_read_node(stripe,elem_type,total)
        out=[]; pos=0
        for ln in lengths:
            out.append(list(elems[pos:pos+ln])); pos+=ln
        return interleave(out)
    if kind==TK_MAP:
        if len(typ.get('subtypes',[]))<2: return interleave([{} for _ in range(nonnull)])
        kt,vt=typ['subtypes'][0],typ['subtypes'][1]
        lengths=stripe.int_reader(col_id,SK_LENGTH,False).read(nonnull) if nonnull else []
        total=sum(lengths)
        keys=_read_node(stripe,kt,total); vals=_read_node(stripe,vt,total)
        out=[]; pos=0
        for ln in lengths:
            m={}
            for j in range(ln):
                k=keys[pos+j]
                try: m[k]=vals[pos+j]
                except Exception: m[str(k)]=vals[pos+j]
            out.append(m); pos+=ln
        return interleave(out)
    if kind==TK_UNION:
        tags=stripe.int_reader(col_id,SK_DATA,False).read(nonnull) if nonnull else []
        subtype_vals={}
        for si,sub in enumerate(typ.get('subtypes',[])):
            cnt=sum(1 for t in tags if t==si)
            subtype_vals[si]=iter(_read_node(stripe,sub,cnt))
        out=[next(subtype_vals[t]) if t in subtype_vals else None for t in tags]
        return interleave(out)
    # primitive
    vals=_read_primitive(stripe,col_id,typ,nonnull)
    return interleave(vals)

def _read_primitive(stripe,col_id,typ,count):
    if count==0: return []
    col=stripe.cols.get(col_id)
    if col is None: return [None]*count
    kind=typ['kind']; enc=col.encoding_kind
    is_dict = enc in (ENC_DICTIONARY,ENC_DICTIONARY_V2)
    if kind==TK_BOOLEAN:
        key=('bool',col_id)
        if key not in stripe._readers:
            stripe._readers[key]=_ByteRLE(col.stream(SK_DATA))
        return stripe._readers[key].read_bools(count)
    if kind==TK_BYTE:
        key=('byte',col_id)
        if key not in stripe._readers:
            stripe._readers[key]=_ByteRLE(col.stream(SK_DATA))
        raw=stripe._readers[key].read_bytes(count)
        return [b-256 if b>127 else b for b in raw]
    if kind in (TK_SHORT,TK_INT,TK_LONG,TK_DATE):
        signed=True
        if is_dict:
            dict_vals=_read_dictionary_primitive(stripe,col_id,typ)
            idx=stripe.int_reader(col_id,SK_DATA,False).read(count)
            return [dict_vals[j] if 0<=j<len(dict_vals) else None for j in idx]
        vals=stripe.int_reader(col_id,SK_DATA,signed).read(count)
        if kind==TK_DATE:
            return [(datetime.date(1970,1,1)+datetime.timedelta(days=int(v))).isoformat() if v is not None else None for v in vals]
        return vals
    if kind in (TK_FLOAT,TK_DOUBLE):
        data=col.stream(SK_DATA)
        key=('floatpos',col_id)
        pos=stripe._readers.get(key,0)
        vals=[]
        if kind==TK_FLOAT:
            for _ in range(count):
                vals.append(struct.unpack_from('<f',data,pos)[0]); pos+=4
        else:
            for _ in range(count):
                vals.append(struct.unpack_from('<d',data,pos)[0]); pos+=8
        stripe._readers[key]=pos
        if is_dict:
            idx=stripe.int_reader(col_id,SK_DATA,False).read(count)
            # (float dictionary is not used in ORC) ignore
        return vals
    if kind in (TK_STRING,TK_VARCHAR,TK_CHAR,TK_BINARY):
        if is_dict:
            dict_vals=_read_string_dictionary(stripe,col_id)
            idx=stripe.int_reader(col_id,SK_DATA,False).read(count)
            vals=[dict_vals[j] if 0<=j<len(dict_vals) else None for j in idx]
        else:
            lengths=stripe.int_reader(col_id,SK_LENGTH,False).read(count)
            data=col.stream(SK_DATA)
            key=('bytespos',col_id)
            pos=stripe._readers.get(key,0)
            vals=[]
            for ln in lengths:
                vals.append(bytes(data[pos:pos+ln])); pos+=ln
            stripe._readers[key]=pos
        if kind==TK_BINARY:
            return [base64.b64encode(v).decode() if isinstance(v,(bytes,bytearray)) else v for v in vals]
        out=[]
        for v in vals:
            if isinstance(v,(bytes,bytearray)):
                s=bytes(v).decode('utf-8','surrogateescape')
            else: s=v
            if kind==TK_CHAR and isinstance(s,str):
                s=s.rstrip(' ')
            out.append(s)
        return out
    if kind in (TK_TIMESTAMP,TK_TIMESTAMP_INSTANT):
        seconds=stripe.int_reader(col_id,SK_DATA,True).read(count)
        nanos_encoded=[]
        if (SK_SECONDARY,0) in col.streams:
            nanos_encoded=stripe.int_reader(col_id,SK_SECONDARY,False).read(count)
        else:
            nanos_encoded=[0]*count
        out=[]
        for sec,nenc in zip(seconds,nanos_encoded):
            nanos=_decode_timestamp_nanos(nenc)
            if kind==TK_TIMESTAMP_INSTANT:
                base=datetime.datetime(1970,1,1,tzinfo=datetime.timezone.utc)
                dt=base+datetime.timedelta(seconds=int(sec),microseconds=nanos//1000)
            else:
                base=datetime.datetime(2015,1,1,0,0,0)
                # writer timezone: Go ORC library converts to time in writer tz then JSON outputs with tz? Asset values are UTC Z.
                dt=base+datetime.timedelta(seconds=int(sec),microseconds=nanos//1000)
                dt=dt.replace(tzinfo=datetime.timezone.utc)
            from .yamlmini import format_go_time
            out.append(format_go_time(dt))
        return out
    if kind==TK_DECIMAL:
        data=col.stream(SK_DATA)
        key=('decpos',col_id)
        pos=stripe._readers.get(key,0)
        unscaled=[]
        for _ in range(count):
