import json,struct,zlib,os
def long(v):
    zz=(v<<1) ^ (v>>63) if v>=0 else ((-v<<1)-1)
    out=b''
    while True:
        b=zz&0x7f; zz>>=7
        if zz: out+=bytes([b|0x80])
        else: out+=bytes([b]); break
    return out
def bytes_(b):
    if isinstance(b,str): b=b.encode()
    return long(len(b))+b
def enc(schema,val,named=None):
    named=named or {}
    if isinstance(schema,list):
        idx,inner=val
        return long(idx)+enc(schema[idx],inner,named)
    if isinstance(schema,str):
        if schema in named: return enc(named[schema],val,named)
        if schema=='null': return b''
        if schema=='boolean': return bytes([1 if val else 0])
        if schema in ('int','long'): return long(val)
        if schema=='float': return struct.pack('<f',val)
        if schema=='double': return struct.pack('<d',val)
        if schema=='bytes': return bytes_(val)
        if schema=='string': return bytes_(val)
        raise ValueError(schema)
    if isinstance(schema,dict):
        typ=schema.get('type')
        if isinstance(typ,(dict,list)): return enc(typ,val,named)
        if typ=='record':
