class _RecordAssembler:
    def __init__(self, root, leaves, leaf_triples):
        self.root=root
        self.leaves=leaves
        self.triples=leaf_triples
        self.pos=[0]*len(leaf_triples)
        # assign leaf index to leaf nodes in DFS order by identity order of leaves list
        for i,leaf in enumerate(leaves):
            leaf['node']['_leaf_index']=i
    def _first_leaf_index(self,node):
        if '_leaf_index' in node:
            return node['_leaf_index']
        for ch in node.get('children') or []:
            idx=self._first_leaf_index(ch)
            if idx is not None:
                return idx
        return None
    def _leaf_indices(self,node):
        if '_leaf_index' in node:
            return [node['_leaf_index']]
        out=[]
        for ch in node.get('children') or []:
            out.extend(self._leaf_indices(ch))
        return out
    def _peek(self,node):
        idx=self._first_leaf_index(node)
        if idx is None: return None
        if self.pos[idx] >= len(self.triples[idx]): return None
        return self.triples[idx][self.pos[idx]]
    def _consume_leaf(self,idx):
        if self.pos[idx] < len(self.triples[idx]):
            t=self.triples[idx][self.pos[idx]]; self.pos[idx]+=1; return t
        return (0,0,None)
    def _consume_subtree(self,node):
        for idx in self._leaf_indices(node):
            self._consume_leaf(idx)
    def read_record(self):
        return self._read_field(self.root,0,0)
    def _is_list(self,node):
        conv=node.get('converted')
        log=_logical_info(node)
        return conv==3 or log.get('kind_id')==3
    def _is_map(self,node):
        conv=node.get('converted')
        log=_logical_info(node)
        return conv in (1,2) or log.get('kind_id')==2
    def _read_field(self,node,parent_def,parent_rep):
        if self._is_list(node):
            return self._read_list(node,parent_def,parent_rep)
        if self._is_map(node):
            return self._read_map(node,parent_def,parent_rep)
        rep=node.get('repetition') or 0
        if rep==2:
            res=self._read_repeated(node,parent_def,parent_rep)
            return None if res is _EMPTY else res
        return self._read_single(node,parent_def,parent_rep)
    def _read_single(self,node,parent_def,parent_rep):
        rep=node.get('repetition') or 0
        current_def=parent_def
        if rep==1:
            t=self._peek(node)
            if t is not None and t[1]==parent_def:
                self._consume_subtree(node)
                return None
            current_def=parent_def+1
        return self._read_instance(node,current_def,parent_rep)
    def _read_instance(self,node,current_def,current_rep):
        children=node.get('children') or []
        if not children:
            idx=node.get('_leaf_index')
            if idx is None:
                return {}
            t=self._consume_leaf(idx)
            return _convert_value(t[2],node)
        out={}
        for ch in children:
            out[mangle_name(ch['name'])]=self._read_field(ch,current_def,current_rep)
        return out
    def _read_repeated(self,node,parent_def,parent_rep):
        R=parent_rep+1
        t=self._peek(node)
        if t is None:
            return _EMPTY
        if t[1]==parent_def:
            self._consume_subtree(node)
            return _EMPTY
        items=[]
        while True:
            item=self._read_instance(node,parent_def+1,R)
            items.append(item)
            t=self._peek(node)
            if t is None or t[0] < R:
                break
        return items
    def _read_list(self,node,parent_def,parent_rep):
        current_def=parent_def
        rep=node.get('repetition') or 0
        if rep==1:
            t=self._peek(node)
            if t is not None and t[1]==parent_def:
                self._consume_subtree(node)
                return None
            current_def=parent_def+1
        children=node.get('children') or []
        if not children:
            return []
        repeated_child=children[0]
        if (repeated_child.get('repetition') or 0)!=2:
            # malformed list: treat single child as one element
            v=self._read_field(repeated_child,current_def,parent_rep)
            return [v]
        res=self._read_repeated(repeated_child,current_def,parent_rep)
        if res is _EMPTY:
            return []
        # unwrap 3-level single-field group elements
        if (repeated_child.get('children') or []) and len(repeated_child.get('children'))==1:
            key=mangle_name(repeated_child['children'][0]['name'])
            return [ (it.get(key) if isinstance(it,dict) else it) for it in res]
        return res
    def _read_map(self,node,parent_def,parent_rep):
        current_def=parent_def
        rep=node.get('repetition') or 0
        if rep==1:
            t=self._peek(node)
            if t is not None and t[1]==parent_def:
                self._consume_subtree(node)
                return None
            current_def=parent_def+1
        children=node.get('children') or []
        if not children:
            return {}
        kv=children[0]
        res=self._read_repeated(kv,current_def,parent_rep)
        if res is _EMPTY:
            return {}
        out={}
        kv_children=kv.get('children') or []
        if len(kv_children)>=1:
            key_name=mangle_name(kv_children[0]['name'])
            val_name=mangle_name(kv_children[1]['name']) if len(kv_children)>=2 else None
            for entry in res:
                if not isinstance(entry,dict): continue
                k=entry.get(key_name)
                v=entry.get(val_name) if val_name else None
                if isinstance(k,bool):
                    ks='true' if k else 'false'
                elif isinstance(k,(int,float)):
                    ks=str(k)
                elif k is None:
                    ks='null'
                else:
                    ks=str(k)
                out[ks]=v
        return out

class _Empty: pass
_EMPTY=_Empty()
'''
