import sys,subprocess,json,zlib,binascii,os
sys.path.insert(0,'/tmp')
from avro_writer import enc,long,bytes_
import json as js
def snappy_literal(data):
    out=b''; n=len(data); x=n
    while True:
        b=x&0x7f; x>>=7
        if x: out+=bytes([b|0x80])
        else: out+=bytes([b]); break
    i=0
    while i<len(data):
        chunk=data[i:i+60]; out+=bytes([(len(chunk)-1)<<2])+chunk; i+=len(chunk)
    return out
def write_codec(path,schema,rows,codec):
    sync=b'0123456789abcdef'
    meta=[(b'avro.schema',js.dumps(schema).encode()),(b'avro.codec',codec.encode())]
    out=b'Obj\x01'+long(len(meta))
    for k,v in meta: out+=bytes_(k)+bytes_(v)
    out+=long(0)+sync
    block=b''.join(enc(schema,r) for r in rows)
    if codec=='deflate':
        comp=zlib.compress(block)[2:-4]
    elif codec=='snappy':
        comp=snappy_literal(block)+struct.pack('>I',binascii.crc32(block)&0xffffffff)
    else: comp=block
    import struct
    out+=long(len(rows))+long(len(comp))+comp+sync
    open(path,'wb').write(out)
