import math, re, hashlib, base64
from .gojson import format_float_g
from .util import GoPanicError

class SQLFuncError(Exception):
    pass

def _parse_float_text(s):
    # Go strconv.ParseFloat (without spaces), returning value even on range error (inf/0)
    t=s
    low=t.lower()
    if low in ('nan','+nan','-nan'): return math.nan
    if low in ('inf','+inf','infinity','+infinity'): return math.inf
    if low in ('-inf','-infinity'): return -math.inf
    # hex float
    try:
