def sqlite_printf(fmt, *args):
    # Minimal SQLite printf()/format() implementation for common format specifiers.
    if fmt is None:
        return None
    fmt_s = to_string(fmt) if not isinstance(fmt,(bytes,bytearray)) else fmt.decode('utf-8','surrogateescape')
