    return _sqlite_printf(fmt_s, args)

def _sqlite_printf(fmt_s, args):
    out=[]; i=0; argi=0
    n=len(fmt_s)
    while i<n:
        c=fmt_s[i]
        if c!='%':
            out.append(c); i+=1; continue
        i+=1
        if i>=n:
            out.append('%'); break
        if fmt_s[i]=='%':
            out.append('%'); i+=1; continue
