        start_spec=i-1
        # positional arg like %2$s (SQLite supports %NNN$)
        pos_arg=None
        j=i
        while j<n and fmt_s[j].isdigit(): j+=1
        if j>i and j<n and fmt_s[j]=='$':
            pos_arg=int(fmt_s[i:j]); i=j+1
        flags=''
        while i<n and fmt_s[i] in '-+ #0!,':
            flags+=fmt_s[i]; i+=1
        width=None
        if i<n and fmt_s[i]=='*':
            # width from arg
