            width=int(to_float(wv)) if wv is not None else 0
            i+=1
        else:
            ws=''
            while i<n and fmt_s[i].isdigit(): ws+=fmt_s[i]; i+=1
            if ws: width=int(ws)
        prec=None
        if i<n and fmt_s[i]=='.':
            i+=1
            if i<n and fmt_s[i]=='*':
                pv=args[argi] if argi < len(args) else None; argi+=1; prec=int(to_float(pv)) if pv is not None else 0; i+=1
            else:
                ps=''
                while i<n and fmt_s[i].isdigit(): ps+=fmt_s[i]; i+=1
                prec=int(ps) if ps else 0
