class _AggStats:
    def __init__(self,kind,percentile=None):
        self.kind=kind; self.percentile=percentile; self.values=[]; self.raw=[]
    def step(self,*args):
        if self.kind=='percentile':
            # args: (value, p) or (value,)
            if len(args)>=2:
                self.percentile=args[1]
            v=args[0] if args else None
        else:
            v=args[0] if args else None
        self.raw.append(v)
        self.values.append(to_float(v))
    def final(self):
        if self.kind in ('stdev','stddev','stddev_pop'):
            n=len(self.values)
            if n<=1: return 0
            mean=sum(self.values)/n
            return sum((x-mean)**2 for x in self.values)/(n-1)
        if self.kind=='median':
            if not self.raw: return 0
            # Sort by float value but return original raw value at upper median index (for strings, to_float gives 0 for all... original returned 'b' for strings, so sort raw for strings)
            # Determine sort key: if all raw are strings, sort strings; else sort by float
            if all(isinstance(x,str) for x in self.raw):
                srt=sorted(self.raw)
            else:
                pairs=sorted(zip(self.values,self.raw),key=lambda p:p[0])
                srt=[r for _,r in pairs]
            return srt[len(srt)//2]
        if self.kind=='mode':
            if not self.raw: return 0
            counts={}
            order=[]
            for v in self.raw:
                key=(type(v).__name__,v) if isinstance(v,(str,int,float,bool,type(None))) else str(v)
                if key not in counts:
                    counts[key]=[0,v]; order.append(key)
                counts[key][0]+=1
            best=None; bestc=-1
            for key in order:
                if counts[key][0]>bestc:
                    bestc=counts[key][0]; best=counts[key][1]
            return best
        if self.kind=='percentile':
            if not self.values: return 0
            p=self.percentile
            if p is None:
                return 0
            pf=to_float(p)
            srt=sorted(self.raw, key=lambda x: to_float(x)) if not all(isinstance(x,str) for x in self.raw) else sorted(self.raw)
            # index = ceil(p/100 * n) (1-based), p=0 -> 0 value 0
            import math as _m
            idx=int(_m.ceil(pf/100.0*len(srt)))
            if idx<=0:
                return 0
            if idx>len(srt): idx=len(srt)
            return srt[idx-1]
        return 0

